local config = {
  ui_story_5087_50870100_1_dialog_content = "Ini adalah fabel kuno yang dikenal oleh semua orang di Northland.",
  ui_story_5087_50870100_2_dialog_content = "Dan baris pertama adalah...",
  ui_story_5087_50870100_3_dialog_content = "\"Dapatkah kamu mengingat bunga putih yang indah itu?\"",
  ui_story_5087_50870100_4_dialog_content = "<color=#e8d9bb>Setelah mengingat kalimat pertama, potongan-potongan memori yang tersisa aktif dan muncul satu per satu.</color>",
  ui_story_5087_50870100_5_dialog_content = "<color=#e8d9bb>Api ceria membakar di perapian, cahaya hangatnya menciptakan bayangan yang menari dalam pondok kecil.</color>",
  ui_story_5087_50870100_6_dialog_content = "<color=#e8d9bb>Di bawah cahaya api, empat sosok dapat terlihat: suami dan istri, serta putri kembar mereka yang tampak seperti cerminan satu sama lain.</color>",
  ui_story_5087_50870100_7_dialog_content = "\"Dapatkah kamu mengingat bunga putih yang indah itu? Dua batang tumbuh dalam harmoni di tepi danau yang tenang.\"",
  ui_story_5087_50870100_8_dialog_content = "\"Satu adalah bunga narkissos yang lembut, yang lainnya adalah lili yang murni.\"",
  ui_story_5087_50870100_9_dialog_content = "\"Meskipun berbeda bentuk, jiwa mereka adalah satu.\"",
  ui_story_5087_50870100_10_dialog_content = "\"Satu menghasilkan daun, yang lainnya mekar dengan bunga. Mereka menyeruput embun pagi, akar mereka selamanya terjalin.\"",
  ui_story_5087_50870100_11_dialog_content = "Karena mereka sangat dekat, mereka pasti sudah hidup bersama selamanya, 'kan?",
  ui_story_5087_50870100_12_dialog_content = "Sayangnya, setiap cerita pasti memiliki liku-likunya.",
  ui_story_5087_50870100_13_dialog_content = "\"Di bawah salju abu-abu yang turun, lili murni itu segera terkubur.\"",
  ui_story_5087_50870100_14_dialog_content = "\"Ditinggalkan sendirian di dunia, White Narcissus menangis dengan hening.\"",
  ui_story_5087_50870100_15_dialog_content = "*bersin* Lily yang malang... Pasti sangat dingin di bawah semua salju itu.",
  ui_story_5087_50870100_16_dialog_content = "Saya merasa lebih kasihan pada bunga narcissus. Bukankah ada orang yang bisa membantunya?",
  ui_story_5087_50870100_17_dialog_content = "Kalian berdua adalah gadis-gadis kecil yang manis, seperti lili dan narsis. Northland tidak akan pernah membiarkan kalian menangis sendirian.",
  ui_story_5087_50870100_18_dialog_content = "Mari kita kembali ke cerita—",
  ui_story_5087_50870100_19_dialog_content = "\"Lake Mirror suatu hari menyadari akar-akar dingin dan air mata sedih dari narcissus. Merasa kasihan padanya, danau berjanji untuk mengembalikan jiwa lily.\"",
  ui_story_5087_50870100_20_dialog_content = "Lalu apa yang terjadi? Apakah jiwanya kembali?",
  ui_story_5087_50870100_21_dialog_content = "Apakah mereka bisa hidup bahagia selamanya lagi?",
  ui_story_5087_50870100_22_dialog_content = "Tentu saja mereka melakukannya! Bagaimana lagi cerita itu bisa berakhir?",
  ui_story_5087_50870100_23_dialog_content = "Tapi ini sudah jauh melewati waktu tidurmu, gadis-gadis. Mari kita selesaikan ceritanya besok, setuju?",
  ui_story_5087_50870100_24_dialog_content = "Tidak mungkin! Aku ingin mendengarnya sekarang!",
  ui_story_5087_50870100_25_dialog_content = "Kamu ingin tahu apakah bunga narcissus masih mengenali jiwa bunga lili, bukan?",
  ui_story_5087_50870100_26_dialog_content = "Ya! Aku juga ingin tahu apakah mereka bisa bersama lagi dan hidup bahagia selamanya!",
  ui_story_5087_50870100_27_dialog_content = "Tentu saja mereka melakukannya. Begitulah setiap cerita, 'kan?",
  ui_story_5087_50870100_28_dialog_content = "Tak peduli berapa banyak liku-liku yang diambil oleh cerita ini...",
  ui_story_5087_50870100_29_dialog_content = "Setiap orang selalu mendapatkan hidup bahagia selamanya.",
  ui_story_5087_50870100_30_dialog_content = "Benar. Lola pernah bilang bahwa setiap cerita memiliki akhir yang bahagia.",
  ui_story_5087_50870100_31_dialog_content = "Tapi setelah bertahun-tahun, aku bahkan tidak ingat pernah mendengar cerita ini, apalagi akhirnya.",
  ui_story_5087_50870100_32_dialog_content = "Rasa tidak nyaman mendorong saya untuk mencari jawaban, tetapi yang bisa saya lakukan hanyalah menyaring potongan-potongan kacau dari ingatan saya untuk mencarinya.",
  ui_story_5087_50870100_33_dialog_content = "Kemudian, seolah-olah keinginanku telah dikabulkan, aku akhirnya ingat sesuatu—",
  ui_story_5087_50870100_34_dialog_content = "Sebuah perapian yang hangat, cerita yang diceritakan oleh seorang ibu dan ayah, dan dua gadis kecil yang ceria. Semuanya terasa begitu akrab, namun sekaligus juga terasa begitu jauh.",
  ui_story_5087_50870100_35_dialog_content = "Apakah itu masa laluku? Saya hampir tidak bisa menentukan siapa saya lagi, tetapi makna di balik akhir cerita itu jelas dan terdefinisi.",
  ui_story_5087_50870100_36_dialog_content = "Saya berharap dan berdoa dengan sepenuh hati agar akhir itu menjadi kenyataan, meskipun itu berarti... saya tidak akan pernah bisa bangun lagi.",
  ui_story_5087_50870100_37_dialog_content = "<color=#e8d9bb>\"Sejak hari itu, bunga lili mekar dari narkissos, dan mereka berdua hidup bahagia selama-lamanya...\"</color>",
  ui_story_5087_50870100_38_dialog_content = "Bahagia... selamanya...",
  ui_story_5087_50870100_39_dialog_content = "Benar, Nikinis. Kamu dan saya akan selalu bersama, dan hidup bahagia selamanya.",
  ui_story_5087_50870100_40_dialog_content = "…Hah?",
  ui_story_5087_50870100_41_dialog_content = "<color=#e8d9bb>Aroma memabukkan mengalir melintasi ladang bunga. Aroma ringan dari bunga narsis dan aroma kaya dari bunga lili bercampur di udara.</color>",
  ui_story_5087_50870100_42_dialog_content = "<color=#e8d9bb>Di antara aroma bunga, seseorang berpegangan tangan dengan Nikinis.</color>",
  ui_story_5087_50870100_43_dialog_content = "<color=#e8d9bb>Dia seputih dan secantik bunga lili putih. Meskipun mereka berbeda dalam tubuh dan pikiran, roh mereka adalah satu.</color>",
  ui_story_5087_50870100_44_dialog_content = "N-Nepolis? Apakah itu benar-benar kamu, saudariku?",
  ui_story_5087_50870100_45_dialog_content = "Kenapa kamu terlihat sangat terkejut, Nikinis? Jangan bilang kamu sakit lagi dan lupa bagaimana wajahku.",
  ui_story_5087_50870100_46_dialog_content = "Tentu saja tidak! Tapi aku pikir kamu terjebak di...",
  ui_story_5087_50870100_47_dialog_content = "(... Terjebak dalam apa? Mengapa aku tidak bisa mengingat?)",
  ui_story_5087_50870100_48_dialog_content = "... Tunggu, Nepolis, jangan pergi! Tetap bersamaku!",
  ui_story_5087_50870100_49_dialog_content = "Oh? Sepertinya aku tidak salah lihat. Sejak kita pulih dari sakit, kamu menjadi lebih lengket.",
  ui_story_5087_50870100_50_dialog_content = "Tapi jangan khawatir, Nikinis. Aku benar-benar di sini di sampingmu.",
  ui_story_5087_50870100_51_dialog_content = "Bukan ilusi di cermin, atau pantulan di air.",
  ui_story_5087_50870100_52_dialog_content = "Wajahmu sangat hangat, Nepolis... Apakah kamu benar-benar kembali lagi?",
  ui_story_5087_50870100_53_dialog_content = "(... Kenapa aku bilang \"kembali lagi\"?)",
  ui_story_5087_50870100_54_dialog_content = "Setiap kali kita bersama, rasanya aku bahkan tidak bisa menyembunyikan pikiranku darimu.",
  ui_story_5087_50870100_55_dialog_content = "Saya selalu bisa tahu apa yang kamu pikirkan, dan hal yang sama berlaku untuk kamu dan pikiran saya. Itu adalah hadiah kita dan cara kita menunjukkan bahwa kita akan selalu memiliki satu sama lain.",
  ui_story_5087_50870100_56_dialog_content = "Sekarang ulurkan tanganmu dan berjalanlah bersamaku. Kamu akan segera mengingat semuanya.",
  ui_story_5087_50870100_57_dialog_content = "Sebagai kembar, kami memiliki akar dan batang yang sama. Terlahir dengan Luminatics yang sangat spesial, hati dan jiwa kami terhubung.",
  ui_story_5087_50870100_58_dialog_content = "Jika aku merasa haus...",
  ui_story_5087_50870100_59_dialog_content = "... Maka aku juga akan haus.",
  ui_story_5087_50870100_60_dialog_content = "Jika saya memutuskan untuk keluar...",
  ui_story_5087_50870100_61_dialog_content = "... Aku sudah menyiapkan mantel dan sepatu bot kita.",
  ui_story_5087_50870100_62_dialog_content = "Benar! Penampilan kita, hobi kita, bakat kita... Kamu dan aku adalah satu dan sama, Nikinis.",
  ui_story_5087_50870100_63_dialog_content = "Kami menanam ladang bunga ini bersama, memasuki Winter Palace bersama, dan mendapatkan kehormatan untuk melayani Queen Bethlehem bersama.",
  ui_story_5087_50870100_64_dialog_content = "Kamu... benar-benar tidak ingat apa-apa?",
  ui_story_5087_50870100_65_dialog_content = "Tidak... Aku ingat semuanya sekarang. Semakin kamu bercerita tentang masa lalu kita, semakin banyak kenangan yang muncul di pikiranku.",
  ui_story_5087_50870100_66_dialog_content = "Setiap kali kamu tersenyum dengan nostalgia, aku juga merasakan kebahagiaan yang sama di hatiku.",
  ui_story_5087_50870100_67_dialog_content = "Bersama kamu membuatku merasa begitu... lengkap—setidaknya itulah cara aku mendeskripsikannya.",
  ui_story_5087_50870100_68_dialog_content = "Tak bisa kubayangkan hidup tanpa kamu.",
  ui_story_5087_50870100_69_dialog_content = "Kamu bicara tentang waktu kita berdua sakit, kan? Itu adalah waktu yang sangat menakutkan...",
  ui_story_5087_50870100_70_dialog_content = "Aku merasa sangat lemah dan lesu setiap hari. Aku bahkan tidak bisa merasakan anggota tubuhku sendiri, apalagi kamu.",
  ui_story_5087_50870100_71_dialog_content = "Saya rasa itu adalah kali pertama kita kehilangan koneksi satu sama lain.",
  ui_story_5087_50870100_72_dialog_content = "Benar... Aku juga sakit, itulah sebabnya kenangan dan perasaanku menjadi sangat kacau.",
  ui_story_5087_50870100_73_dialog_content = "Hehe... Lalu kita masih sama seperti saat kita masih anak-anak, berbagi setiap momen sakit dan kesedihan.",
  ui_story_5087_50870100_74_dialog_content = "Sejujurnya, ini sedikit tidak nyaman. Ketika salah satu dari kami sakit, yang lainnya mengikuti... Orang tua kami pasti sangat khawatir!",
  ui_story_5087_50870100_75_dialog_content = "Orang tua kita... Benar! Apakah mereka baik-baik saja? Bisakah aku pulang dan menemui mereka?",
  ui_story_5087_50870100_76_dialog_content = "Tentu saja. Tapi sebelum kita pulang, kita harus menyelesaikan misi kita.",
  ui_story_5087_50870100_77_dialog_content = "Misi kita?",
  ui_story_5087_50870100_78_dialog_content = "Apa, kamu lupa semua tentang misi Her Majesty setelah tidur siang sebentar?",
  ui_story_5087_50870100_79_dialog_content = "Ratu memerintahkan kami untuk mengambil artefak yang hilang dari hutan.",
  ui_story_5087_50870201_1_dialog_content = "Kami tidak punya banyak waktu, jadi mari kita lakukan hal-hal seperti biasanya. Kita akan membersihkan salju sambil bergerak!",
  ui_story_5087_50870201_2_dialog_content = "Baiklah!",
  ui_story_5087_50870201_3_dialog_content = "Misi kita adalah... mengambil kembali artefak yang hilang untuk Queen Bethlehem?",
  ui_story_5087_50870201_4_dialog_content = "Ya. Sebuah relik telah dicuri dari gudang harta Karaton Musim Dingin. Itu adalah objek berbahaya yang dapat mengganggu semangat seseorang.",
  ui_story_5087_50870201_5_dialog_content = "Ratu khawatir bahwa hal itu akan menyebabkan penderitaan yang tak terhitung jika sampai jatuh ke tangan orang banyak, jadi dia mengirim banyak pengikut setianya untuk mencarinya.",
  ui_story_5087_50870201_6_dialog_content = "Dicuri? Jenis pencuri apa yang cukup bodoh untuk melakukan hal seperti itu?",
  ui_story_5087_50870201_7_dialog_content = "Heehee, aku rasa pertanyaan yang lebih baik adalah, ratu jenis apa yang akan begitu pengampun tentang hal ini?",
  ui_story_5087_50870201_8_dialog_content = "Sebuah peninggalan tak ternilai dicuri dari istananya, dan kekhawatiran pertamanya adalah untuk mengambilnya kembali sebelum bisa mengancam keamanan rakyatnya. Bagi Yang Mulia Ratu, menangkap pencuri jauh kurang penting.",
  ui_story_5087_50870201_9_dialog_content = "Ratu selalu seperti itu.",
  ui_story_5087_50870201_10_dialog_content = "Saya tidak bisa menghitung berapa banyak cerita yang telah saya dengar tentang Yang Mulia Ratu menyelesaikan berbagai macam masalah untuk rakyatnya.",
  ui_story_5087_50870201_11_dialog_content = "Meskipun itu hanya sesuatu yang sepele seperti menyelamatkan ternak dari hutan atau membersihkan salju dari jalan pegunungan...",
  ui_story_5087_50870201_12_dialog_content = "Setidaknya kita tidak perlu khawatir tentang salju, kan? Lihat betapa baiknya kita bekerja sama? Hei, ini bagianku!",
  ui_story_5087_50870201_13_dialog_content = "Ratu telah merawat kami selama yang bisa aku ingat...",
  ui_story_5087_50870201_14_dialog_content = "Dia bahkan menyembuhkan penyakitku.",
  ui_story_5087_50870201_15_dialog_content = "Itulah sebabnya kamu memilih untuk tinggal di Winter Palace dan melayaninya.",
  ui_story_5087_50870201_16_dialog_content = "Saya yakin dia juga menyembuhkan penyakitmu.",
  ui_story_5087_50870201_17_dialog_content = "Selama kamu merasa lebih baik, aku juga merasa demikian. Tidak perlu repot-repot memberitahu Ratu tentang hal ini.",
  ui_story_5087_50870201_18_dialog_content = "Satu lagi! Fiuh, akhirnya kita berhasil.",
  ui_story_5087_50870201_19_dialog_content = "Seseorang melaporkan melihat artefak curian di dekat pondok itu di depan.",
  ui_story_5087_50870201_20_dialog_content = "Halo, apakah ada orang di rumah? Kami dikirim oleh Winter Palace.",
  ui_story_5087_50870201_21_dialog_content = "<color=#e8d9bb>Di dalam pondok itu sunyi sepi.</color>",
  ui_story_5087_50870201_22_dialog_content = "(Tidak ada respon... Hah? Saya menginjak sesuatu yang berkilau... serpihan yang rusak dari jenis apa pun?)",
  ui_story_5087_50870201_23_dialog_content = "Apa itu, Nikinis?",
  ui_story_5087_50870201_24_dialog_content = "Hati-hati, Nepolis. Saya memiliki...",
  ui_story_5087_50870201_25_dialog_content = "...Firasat buruk tentang ini.",
  ui_story_5087_50870201_26_dialog_content = "<color=#e8d9bb>Kedua saudara kembar itu masing-masing menempatkan tangan mereka di pintu. Berdiri di kedua sisi pintu, mereka dengan hati-hati mendorongnya terbuka.</color>",
  ui_story_5087_50870201_27_dialog_content = "!",
  ui_story_5087_50870201_28_dialog_content = "Apakah itu... sebuah cermin?",
  ui_story_5087_50870201_29_dialog_content = "Benar-benar rusak...",
  ui_story_5087_50870201_30_dialog_content = "(Apa yang terjadi? Entah kenapa, cermin ini terasa begitu akrab bagiku...)",
  ui_story_5087_50870201_31_dialog_content = "(Hah? Apakah aku baru saja melihat seseorang di dalam cermin?)",
  ui_story_5087_50870201_32_dialog_content = "Nikinis... Nikinis...",
  ui_story_5087_50870201_33_dialog_content = "Siapa kamu? Mengapa kamu memanggilku? Dan... apa yang kamu lakukan di cermin ini?",
  ui_story_5087_50870201_34_dialog_content = "Nikinis... Tidak...",
  ui_story_5087_50870201_35_dialog_content = "Aku tidak bisa mendengarmu.",
  ui_story_5087_50870201_36_dialog_content = "Berhenti! Jangan melangkah lagi!",
  ui_story_5087_50870201_37_dialog_content = "!",
  ui_story_5087_50870201_38_dialog_content = "Itu adalah relik yang dicuri dari Winter Palace, Nikinis!",
  ui_story_5087_50870201_39_dialog_content = "Ini disebut Cermin Northland, dan ini adalah salah satu benda paling berbahaya dalam koleksi sang ratu!",
  ui_story_5087_50870201_40_dialog_content = "Ya?",
  ui_story_5087_50870201_41_dialog_content = "(Lalu mengapa seseorang di dalam artefak berbahaya ini memanggilku?)",
  ui_story_5087_50870201_42_dialog_content = "Hati-hati, Nikinis!",
  ui_story_5087_50870201_43_dialog_content = "<color=#e8d9bb>Terkejut, Nikinis hanya bisa melihat pecahan cermin yang berhamburan mulai gemetar.</color>",
  ui_story_5087_50870201_44_dialog_content = "<color=#e8d9bb>Tiba-tiba, berjibun sinar kegelapan meletus dari serpihan dan berkonvergensi.</color>",
  ui_story_5087_50870201_45_dialog_content = "<color=#e8d9bb>Sebuah kehadiran yang samar, tidak berbeda dengan bayangan.</color>",
  ui_story_5087_50870201_46_dialog_content = "Tetap menjauh dari adikku!",
  ui_story_5087_50870202_1_dialog_content = "Nepolis! Apakah kamu terluka? Aku bisa merasakan rasa sakitmu—",
  ui_story_5087_50870202_2_dialog_content = "Ini bukan waktunya untuk menjaga hubungan kita, bodoh. Jika kamu merasakan rasa sakitku, kedua hidup kita akan berbahaya dalam pertempuran.",
  ui_story_5087_50870202_3_dialog_content = "Maaf... Tapi kamu terluka karena aku...",
  ui_story_5087_50870202_4_dialog_content = "Tak bisa dihindari. Lagipula, kamu pasti akan melakukan hal yang sama untukku, bukan?",
  ui_story_5087_50870202_5_dialog_content = "Apa yang baru saja terjadi padamu? Tidak seperti dirimu sama sekali mendekati cermin ajaib itu dengan sembrono.",
  ui_story_5087_50870202_6_dialog_content = "Saya sedang kesulitan memahami emosimu saat ini...",
  ui_story_5087_50870202_7_dialog_content = "Hanya saja... Aku melihat seseorang bergerak di cermin, jadi aku ingin melihat lebih dekat.",
  ui_story_5087_50870202_8_dialog_content = "Kamu melihat seseorang? Apakah kamu yakin itu bukan hanya bayangan kita?",
  ui_story_5087_50870202_9_dialog_content = "Aku... tidak berpikir begitu? Biarkan aku pergi melihat lagi—",
  ui_story_5087_50870202_10_dialog_content = "Saya rasa itu bukan ide yang baik. Cermin itu sangat berbahaya, dan tidak ada yang bisa menebak apa yang bisa terjadi pada kita jika kita mendekatinya.",
  ui_story_5087_50870202_11_dialog_content = "Kami akan menggunakan Luminatics kami untuk mengikatnya dan mengangkutnya kembali ke Winter Palace.",
  ui_story_5087_50870202_12_dialog_content = "... Kamu benar, Nepolis. Mari kita mulai.",
  ui_story_5087_50870202_13_dialog_content = "<color=#e8d9bb>Kedua saudara perempuan itu mengaktifkan Luminatics mereka secara bersamaan. Cabang-cabang hijau tumbuh dari tanah di kedua sisi cermin dan mekar dengan bunga-bunga putih.</color>",
  ui_story_5087_50870202_14_dialog_content = "<color=#e8d9bb>Segera, seluruh pondok dipenuhi dengan aroma bunga. Saat cabang-cabang yang mekar merambat di dinding pondok, cermin yang pecah dibungkus dengan rapat.</color>",
  ui_story_5087_50870202_15_dialog_content = "Argh! Ada sesuatu di dalam cermin... dan itu mencoba keluar!",
  ui_story_5087_50870202_16_dialog_content = "Bertahanlah! Aku datang!",
  ui_story_5087_50870202_17_dialog_content = "Fyuh...",
  ui_story_5087_50870202_18_dialog_content = "Heheh, sepertinya kita berhasil, ya? Aku tidak mengharapkan kurang dari kita berdua sebagai kakak beradik!",
  ui_story_5087_50870202_19_dialog_content = "Kamu pantas mendapatkan semua pujian, Nepolis... Sudah begitu lama sejak pertarungan terakhirku hingga aku lupa untuk berhati-hati.",
  ui_story_5087_50870202_20_dialog_content = "Saya tidak berpikir saya bisa menangani ini tanpa kamu...",
  ui_story_5087_50870202_21_dialog_content = "Sama sekali tidak! Saya bisa melihat betapa kuatnya kamu hanya dari melihat bunga-bunga ini.",
  ui_story_5087_50870202_22_dialog_content = "Lihat? Lihat saja betapa baiknya mereka mekar!",
  ui_story_5087_50870202_23_dialog_content = "<color=#e8d9bb>Dengan kekuatan Luminatics mereka, pondok itu terkubur di bawah lautan bunga putih murni.</color>",
  ui_story_5087_50870202_24_dialog_content = "<color=#e8d9bb>Narcissus halus dan lili murni, lahir berdampingan.</color>",
  ui_story_5087_50870202_25_dialog_content = "Bunga-bunga kita mekar bersama... Entah kenapa, rasanya sudah lama aku tidak melihat hal seperti ini...",
  ui_story_5087_50870202_26_dialog_content = "\"Dapatkah kamu mengingat bunga putih yang indah itu?\"",
  ui_story_5087_50870202_27_dialog_content = "Bunga-bunga Nepolis... Ah.",
  ui_story_5087_50870202_28_dialog_content = "Aku ada di sini, ingat? Kamu tidak perlu terus menatap bunga-bungaku, lho.",
  ui_story_5087_50870202_29_dialog_content = "Setelah kita kembali dari Winter Palace, kita bisa kembali ke Lake Mirror dan merawat ladang bunga kita!",
  ui_story_5087_50870300_1_dialog_content = "<color=#e8d9bb>Winter Palace adalah pusat otoritas kerajaan di Northland dan tempat yang lama dianggap sakral oleh penduduk Northland.</color>",
  ui_story_5087_50870300_2_dialog_content = "Luar biasa... Kalian berdua benar-benar berhasil mendapatkan Northland Mirror! Saya hampir tidak percaya itu!",
  ui_story_5087_50870300_3_dialog_content = "Itu semua berkat saudariku...",
  ui_story_5087_50870300_4_dialog_content = "Jangan terlalu rendah hati, Nikinis! Lihat, mereka bahkan sudah menyajikan teh paling istimewa dari Yang Mulia Ratu untuk kita.",
  ui_story_5087_50870300_5_dialog_content = "Barang ini tidak murah, tahu? Terakhir kali aku ingin secangkir, aku memohon selama tiga hari berturut-turut, tapi mereka masih menolakku.",
  ui_story_5087_50870300_6_dialog_content = "Hahaha, baiklah... Seperti yang kamu tahu, pencurian Cermin Northland adalah masalah yang cukup serius!",
  ui_story_5087_50870300_7_dialog_content = "Mereka mengatakan bahwa relik ini bahkan lebih tua daripada Winter Palace dan memiliki tempat yang sangat unik dalam koleksi sang ratu.",
  ui_story_5087_50870300_8_dialog_content = "Untuk hilang di tengah malam tanpa jejak... kasihan Master Novio hampir tidak tidur sejak itu!",
  ui_story_5087_50870300_9_dialog_content = "Sekarang ini telah kembali dalam kepemilikan kita, keluarga kerajaan bisa menghindari lebih banyak lagi malam tanpa tidur... setidaknya untuk sekarang! Hahaha!",
  ui_story_5087_50870300_10_dialog_content = "Kami merasa terhormat dapat membantu Guru Novio dengan sesuatu yang sangat penting. Sayangnya, kami belum menemukan petunjuk apa pun tentang pencurinya...",
  ui_story_5087_50870300_11_dialog_content = "...",
  ui_story_5087_50870300_12_dialog_content = "Hmm? Ada apa, Nikinis? Kamu tampak gelisah... Apakah kamu gugup berada di Winter Palace yang megah ini?",
  ui_story_5087_50870300_13_dialog_content = "Sejujurnya, aku berharap kamu tidak terlalu sering menggodaku.",
  ui_story_5087_50870300_14_dialog_content = "Hanya saja... Winter Palace tampak sedikit berbeda hari ini.",
  ui_story_5087_50870300_15_dialog_content = "Apa bedanya?",
  ui_story_5087_50870300_16_dialog_content = "(Saya tidak yakin... Kenapa sangat sulit untuk mengingat seperti apa Winter Palace sebelumnya?)",
  ui_story_5087_50870300_17_dialog_content = "Aku tidak bisa menentukan... Mungkin hari ini tampak sangat bersih? Ini sangat cerah dan jernih sehingga rasanya ada yang hilang...",
  ui_story_5087_50870300_18_dialog_content = "Dan di sini saya pikir Anda sangat mementingkan kebersihan.",
  ui_story_5087_50870300_19_dialog_content = "Yang Mulia Ratu!",
  ui_story_5087_50870300_20_dialog_content = "Y-Yang Mulia! Maafkan kami jika pertengkaran kami menyinggung Anda...",
  ui_story_5087_50870300_21_dialog_content = "Tidak ada yang perlu dikecam, Nikinis. Bahkan, aku setuju denganmu. Ketika suatu ruangan terlalu bersih, itu bisa agak mengganggu.",
  ui_story_5087_50870300_22_dialog_content = "Seharusnya istana memiliki lebih banyak tanda kehidupan, seperti asap lilin dan daun teh yang dibuang. Mungkin saya bisa meminta Noah dan yang lainnya untuk membantu saya dengan ini.",
  ui_story_5087_50870300_23_dialog_content = "I-Itu bukan maksud saya, Yang Mulia...",
  ui_story_5087_50870300_24_dialog_content = "Saya pikir ratu sedang memberi tahu kita bahwa kita harus lebih sering berkunjung, saudari.",
  ui_story_5087_50870300_25_dialog_content = "Jika kita menghadiri klub baca dan sesi teh sore Yang Mulia Ratu, kita akan menambahkan lebih banyak \"tanda-tanda kehidupan\" ke istana!",
  ui_story_5087_50870300_26_dialog_content = "Hati-hati, Nepolis! Jangan sampai membakar dirimu sendiri hanya karena sesuatu seperti teh...",
  ui_story_5087_50870300_27_dialog_content = "Heheh... Kadang-kadang kakakku bisa sangat menggemaskan. Apakah Anda setuju, Yang Mulia?",
  ui_story_5087_50870300_28_dialog_content = "Nepolis!",
  ui_story_5087_50870300_29_dialog_content = "Sebagai saudara perempuan, kalian berdua tidak bisa lebih dekat lagi. Ikatan kalian memberikan kekuatan dan kesatuan, dan itulah alasan kalian bisa mendapatkan Cermin Northland.",
  ui_story_5087_50870300_30_dialog_content = "Pekerjaanmu sangat dihargai, Nepolis dan Nikinis.",
  ui_story_5087_50870300_31_dialog_content = "Kami hanya menjalankan tugas kami untuk menjaga keamanan Northland.",
  ui_story_5087_50870300_32_dialog_content = "Yang Mulia, bolehkah saya bertanya... apa yang terjadi pada cermin itu?",
  ui_story_5087_50870300_33_dialog_content = "Cermin Northland dapat mengubah apa pun yang dipantulkannya menjadi kekuatan, yang kemudian berubah menjadi monster yang terbuat dari bayangan.",
  ui_story_5087_50870300_34_dialog_content = "Aku telah menyegel cermin dan monster yang berdiam di dalamnya. Saat ini, mereka tidak menimbulkan ancaman.",
  ui_story_5087_50870300_35_dialog_content = "Kami masih memiliki banyak hal untuk diselidiki terkait pencuriannya. Katakan padaku, apakah kamu melihat sesuatu yang tidak biasa di tempat kamu menemukannya?",
  ui_story_5087_50870300_36_dialog_content = "... Sebenarnya, semua hal tentang adegan itu tidak biasa.",
  ui_story_5087_50870300_37_dialog_content = "Tidak ada orang lain di pondok tempat cermin itu tersembunyi, atau tanda-tanda adanya pencuri sejauh ini...",
  ui_story_5087_50870300_38_dialog_content = "Ketika kami memasuki pondok itu, cermin sudah hancur. Tidak ada petunjuk tentang siapa yang menghancurkannya atau mengapa mereka melakukannya...",
  ui_story_5087_50870300_39_dialog_content = "Lantai itu dipenuhi dengan pecahan cermin yang hancur, dan segera beberapa sinar kegelapan melarikan diri dari mereka. Mereka sangat mirip dengan monster bayangan yang baru saja Anda deskripsikan, Yang Mulia...",
  ui_story_5087_50870300_40_dialog_content = "Nikinis mengatakan bahwa dia juga melihat sosok misterius di dalam cermin.",
  ui_story_5087_50870300_41_dialog_content = "...",
  ui_story_5087_50870300_42_dialog_content = "Monster bayangan dan sosok misterius... Aku khawatir ini semua adalah hasil dari kekuatan Northland Mirror.",
  ui_story_5087_50870300_43_dialog_content = "Kemungkinan besar pencuri secara tidak sengaja mengaktifkan cermin itu dengan terperangkap dalam pantulannya.",
  ui_story_5087_50870300_44_dialog_content = "Jika apa yang kamu katakan itu benar, menyegel cermin itu sendiri tidak akan cukup untuk menjamin keamanan kerajaan.",
  ui_story_5087_50870300_45_dialog_content = "Aku khawatir serpihan-serpihan cermin itu juga mengandung sebagian kekuatan monster-monster itu. Demi keamanan semua orang, mereka semua harus diambil kembali.",
  ui_story_5087_50870300_46_dialog_content = "May Apakah aku juga bisa mempercayakan misi ini kepada kalian berdua?",
  ui_story_5087_50870300_47_dialog_content = "Tentu saja, Yang Mulia! Kami sangat berterima kasih atas setiap kesempatan untuk melayani Anda.",
  ui_story_5087_50870300_48_dialog_content = "Yang Mulia... May Bolehkah saya mengajukan pertanyaan?",
  ui_story_5087_50870300_49_dialog_content = "Dengan segala cara.",
  ui_story_5087_50870300_50_dialog_content = "Ada sesuatu tentang cermin itu yang terasa sangat familiar, seolah-olah kita pernah bertemu jauh di masa lalu...",
  ui_story_5087_50870300_51_dialog_content = "Bisakah kamu jelaskan kenapa aku merasa seperti itu?",
  ui_story_5087_50870300_52_dialog_content = "Sungguh? Itu aneh. Aku sama sekali tidak merasakan hal seperti itu.",
  ui_story_5087_50870300_53_dialog_content = "... Tampaknya tidak ada gunanya menyembunyikannya darimu, Nikinis.",
  ui_story_5087_50870300_54_dialog_content = "Intuisi kamu sepenuhnya benar. Kamu memang pernah bertemu dengan Northland Mirror sebelumnya.",
  ui_story_5087_50870300_55_dialog_content = "Aku tahu itu!",
  ui_story_5087_50870300_56_dialog_content = "Ini terjadi ketika kalian berdua jatuh sakit.",
  ui_story_5087_50870300_57_dialog_content = "Saat itu, Nepolis dilanda demam yang mengerikan, namun kamu dalam keadaan sehat sempurna. Namun seiring waktu, kamu mulai menunjukkan gejala yang serupa.",
  ui_story_5087_50870300_58_dialog_content = "Kalian berdua selalu seperti ini. Hubungan badan dan jiwa kalian membuat kalian dua kali lebih kuat, tetapi juga dua kali lebih rentan.",
  ui_story_5087_50870300_59_dialog_content = "Orang tua Anda dengan putus asa mencari bantuan dari beberapa dokter, tapi semua sia-sia. Pada akhirnya, mereka tidak punya pilihan selain membawa Anda ke istana dan meminta bantuan saya.",
  ui_story_5087_50870300_60_dialog_content = "Untuk mencegah gangguan apa pun terhadap pemulihan Anda, pilihan pertama saya adalah memutuskan sambungan Anda untuk sementara waktu.",
  ui_story_5087_50870300_61_dialog_content = "Untuk itu, aku membutuhkan relik kuat yang mampu mempengaruhi jiwa makhluk hidup—",
  ui_story_5087_50870300_62_dialog_content = "Cermin Northland!",
  ui_story_5087_50870300_63_dialog_content = "Tepat sekali. Saat itu, Anda menunjukkan afinitas yang sangat tinggi untuk Northland Mirror.",
  ui_story_5087_50870300_64_dialog_content = "Itu juga sebabnya aku bisa berhasil memisahkan kalian berdua dan menyembuhkan penyakitmu.",
  ui_story_5087_50870300_65_dialog_content = "...",
  ui_story_5087_50870300_66_dialog_content = "Aku mengerti... Aku rasa aku samar-samar ingat orang tua kita membawa kita ke Istana Musim Dingin untuk pengobatan...",
  ui_story_5087_50870300_67_dialog_content = "Itulah mengapa rasanya begitu akrab! Aku berhutang pada cermin itu untuk hidupku...",
  ui_story_5087_50870300_68_dialog_content = "... Itu adalah kebenaran sebenarnya. Dan sekarang setelah kamu ingat, aku tidak punya alasan untuk menyangkalnya.",
  ui_story_5087_50870300_69_dialog_content = "Tapi ada satu hal yang harus kamu selalu ingat—jangan pernah mendekati cermin, dan jangan pernah percaya kata-kata yang diucapkan oleh pantulannya.",
  ui_story_5087_50870300_70_dialog_content = "Sebagai salah satu peninggalan tertua dan paling kuat di Northland, ia dikelilingi oleh bahaya dan misteri dalam ukuran yang sama tingginya.",
  ui_story_5087_50870300_71_dialog_content = "Bahkan peradaban kuno, yang mampu menciptakan keajaiban seperti Beacon dan Colossus—",
  ui_story_5087_50870300_72_dialog_content = "Mereka berjuta-juta tahun jauhnya dari memahami sepenuhnya kekuatan cermin itu.",
  ui_story_5087_50870400_1_dialog_content = "Pergilah, monster!",
  ui_story_5087_50870400_2_dialog_content = "Graaah...",
  ui_story_5087_50870400_3_dialog_content = "Tidak buruk! Dengan kecepatan ini, kita akan menemukan sisa-sisa fragmen cermin dalam sekejap, dan misi kita akan selesai.",
  ui_story_5087_50870400_4_dialog_content = "... Dan semua itu berkat kemampuanmu merasakan keberadaan cermin itu.",
  ui_story_5087_50870400_5_dialog_content = "Saya hanya senang akhirnya bisa membantu, Nepolis! Bahkan, biarkan saya pergi melihat apakah ada fragmen lain di dekat sini.",
  ui_story_5087_50870400_6_dialog_content = "... Tentu saja. Aku mengandalkanmu.",
  ui_story_5087_50870400_7_dialog_content = "Hah? Ada apa, Nepolis? Kamu tampak sedikit murung.",
  ui_story_5087_50870400_8_dialog_content = "T-Tidak sama sekali! Justru, kamu yang berperilaku berbeda! Apa yang terjadi denganmu?",
  ui_story_5087_50870400_9_dialog_content = "Kurasa tidak mungkin menyembunyikannya darimu.",
  ui_story_5087_50870400_10_dialog_content = "Apakah kamu ingat apa yang Queen Bethlehem katakan tentang Northland Mirror?",
  ui_story_5087_50870400_11_dialog_content = "Tentu saja. Dia mengatakan bahwa kekuatan cermin tidak hanya terbatas pada menciptakan monster...",
  ui_story_5087_50870400_12_dialog_content = "Cermin ini dapat menggunakan apa pun yang tertangkap dalam pantulannya untuk menciptakan ilusi yang realistis, yang kemudian dapat mempengaruhi orang hingga ke jiwa mereka.",
  ui_story_5087_50870400_13_dialog_content = "Karena diciptakan oleh peradaban yang tidak dikenal berabad-abad yang lalu, cermin ini mengandung kekuatan yang luar biasa dan primitif...",
  ui_story_5087_50870400_14_dialog_content = "Baik sang ratu maupun peradaban sebelum zaman kita tidak bisa sepenuhnya memahaminya...",
  ui_story_5087_50870400_15_dialog_content = "Bahkan organisasi paling sesat di Northland, yang merupakan ahli tentang peninggalan kuno seperti ini, benar-benar bingung dengan sihirnya.",
  ui_story_5087_50870400_16_dialog_content = "Untuk membuka potensi penuh dari peninggalan yang begitu kuat ini, diperlukan wadah yang cocok sebagai pembawanya...",
  ui_story_5087_50870400_17_dialog_content = "Tapi menjadi inangnya memberikan peluang yang jauh lebih besar untuk mati sebelum mendapatkan kekuatannya.",
  ui_story_5087_50870400_18_dialog_content = "Nepolis... Meskipun cermin ini bisa sangat berbahaya, Queen Bethlehem mengambil risiko menggunakannya untuk menyelamatkan kita...",
  ui_story_5087_50870400_19_dialog_content = "Sekarang kita tahu kebenaran, giliran kita untuk membalasnya... Tapi hingga saat ini, yang telah kulakukan hanyalah mengandalkan kekuatanmu.",
  ui_story_5087_50870400_20_dialog_content = "Dengan kemampuan saya untuk merasakan keberadaan cermin, akhirnya saya bisa membantu kamu—",
  ui_story_5087_50870400_21_dialog_content = "... Berhenti!",
  ui_story_5087_50870400_22_dialog_content = "N-Nepolis?",
  ui_story_5087_50870400_23_dialog_content = "Kita tidak bisa terlalu mengandalkan afinitasmu dengan cermin, atau membiarkan jiwa Anda terlalu dekat dengannya.",
  ui_story_5087_50870400_24_dialog_content = "\"Siapa pun yang dipilih oleh cermin untuk menjadi tuan rumahnya memiliki peluang lebih tinggi untuk mati sebelum mendapatkan kekuatannya.\" Apakah kamu sudah lupa apa yang diceritakan ratu kepada kita?",
  ui_story_5087_50870400_25_dialog_content = "Kita harus segera mengumpulkan fragmen yang tersisa, dan kemudian kamu tidak diperbolehkan mendekatinya lagi.",
  ui_story_5087_50870400_26_dialog_content = "Setelah misi kita selesai, akhirnya kita bisa pulang ke ladang bunga kita. Kita akan aman, dan hati serta pikiran kita akan menjadi satu lagi...",
  ui_story_5087_50870400_27_dialog_content = "T-Tentu saja! Aku tak akan gegabah mendekati cermin lagi, aku janji!",
  ui_story_5087_50870400_28_dialog_content = "... Dan jika kita harus mendekatinya, biarkan aku yang pergi menggantikanmu. Lagipula, aku tidak memiliki afinitas dengannya.",
  ui_story_5087_50870400_29_dialog_content = "Setiap kali kita membicarakan tentang cermin, rasanya seperti kamu semakin menjauh dariku...",
  ui_story_5087_50870400_30_dialog_content = "Graah!",
  ui_story_5087_50870400_31_dialog_content = "Nepolis! Monster cermin juga datang dari sini!",
  ui_story_5087_50870400_32_dialog_content = "Bergerak, Nikinis!",
  ui_story_5087_50870400_33_dialog_content = "Serahkan hutan ini padaku! ... Hah? Kenapa yang satu itu terlihat berbeda dari yang lainnya?",
  ui_story_5087_50870400_34_dialog_content = "Tahan di sana, monster!",
  ui_story_5087_50870400_35_dialog_content = "Ke mana ia pergi?",
  ui_story_5087_50870400_36_dialog_content = "(Itu bukan ilusi tadi. Sepertinya terbuat dari kristal es... Apakah ini juga hasil dari Northland Mirror?)",
  ui_story_5087_50870400_37_dialog_content = "<color=#e8d9bb>Tiba-tiba, suara gemerisik dapat terdengar dari lebih dalam hutan.</color>",
  ui_story_5087_50870400_38_dialog_content = "(... Dia datang!)",
  ui_story_5087_50870400_39_dialog_content = "...",
  ui_story_5087_50870400_40_dialog_content = "Se-Seorang gadis kecil?",
  ui_story_5087_50870501_1_dialog_content = "Selamat siang.",
  ui_story_5087_50870501_2_dialog_content = "(Anak kecil ini terlihat sangat tenang...)",
  ui_story_5087_50870501_3_dialog_content = "Apa yang kamu lakukan sendirian di hutan, gadis kecil? Apakah rumahmu dekat dari sini?",
  ui_story_5087_50870501_4_dialog_content = "Aku... menjual barang.",
  ui_story_5087_50870501_5_dialog_content = "Oh, ya, kamu membawa keranjang bunga. Itukah yang kamu jual?",
  ui_story_5087_50870501_6_dialog_content = "Saya memiliki barang lain yang dijual juga, tetapi saya belum melakukan bisnis apa pun. Oleh karena itu, saya belum siap untuk pulang.",
  ui_story_5087_50870501_7_dialog_content = "\"Sebagai itu\"? Heheh, untuk seseorang yang begitu muda, kamu pasti tahu bagaimana berbicara seperti orang dewasa. Saya terkesan!",
  ui_story_5087_50870501_8_dialog_content = "A-Aku mempelajarinya dari Ibu dan Ayahku!",
  ui_story_5087_50870501_9_dialog_content = "Jangan khawatir, aku bukan orang jahat. Hutan bisa menjadi tempat yang berbahaya, tahu? Bahkan ada monster yang sedang berkeliaran sekarang ini.",
  ui_story_5087_50870501_10_dialog_content = "Apakah kamu tahu cara pulang? Aku bisa mengantar kamu kembali, jika kamu mau.",
  ui_story_5087_50870501_11_dialog_content = "Aku tidak takut pada monster.",
  ui_story_5087_50870501_12_dialog_content = "B-Begitu? Saya pikir kamu setidaknya harus sedikit takut pada mereka...",
  ui_story_5087_50870501_13_dialog_content = "Satu-satunya yang aku takutkan adalah tidak bisa membantu keluargaku dengan beban mereka. Jadi, bisakah kamu membantuku dengan membeli sesuatu, nona?",
  ui_story_5087_50870501_14_dialog_content = "Seperti cermin tangan ini, misalnya. 'Kan ini sangat cantik?",
  ui_story_5087_50870501_15_dialog_content = "!",
  ui_story_5087_50870501_16_dialog_content = "(Tunggu, aku pikir ini hanya cermin biasa. Syukurlah... Meski begitu, aku tidak yakin Nepolis akan senang jika aku kembali dengan cermin.)",
  ui_story_5087_50870501_17_dialog_content = "Maaf, sayang, tapi akhir-akhir ini aku banyak mendapat nasib buruk dengan cermin.",
  ui_story_5087_50870501_18_dialog_content = "... Baiklah.",
  ui_story_5087_50870501_19_dialog_content = "Lalu... Bagaimana dengan beberapa bunga yang baru dipotong? Apakah Anda bersedia membeli beberapa?",
  ui_story_5087_50870501_20_dialog_content = "Lihat? Aku punya mawar kuning, forget-me-not, dan bahkan beberapa white narcissuses! Salah satu dari ini pasti menarik perhatianmu, kan?",
  ui_story_5087_50870501_21_dialog_content = "Kebetulan sekali! Aku kebetulan paling menyukai semua bunga ini!",
  ui_story_5087_50870501_22_dialog_content = "Saya senang mendengarnya, nona.",
  ui_story_5087_50870501_23_dialog_content = "Maka kamu pasti tahu apa yang mereka <color=#FFB400>simbolkan</color>, bukan?",
  ui_story_5087_50870501_24_dialog_content = "Apa yang mereka lambangkan...",
  ui_story_5087_50870501_25_dialog_content = "Lebih banyak bunga? Betapa baiknya kamu, Nikinis. Lalu, apa yang kamu bawa untukku hari ini? Mawar kuning dan forget-me-nots?",
  ui_story_5087_50870501_26_dialog_content = "Ya, Yang Mulia. Saya selalu ingin memberikan Anda bunga-bunga ini karena apa yang mereka simbolkan—",
  ui_story_5087_50870501_27_dialog_content = "(Ingatan yang baru saja kulihat di pikiranku... Kapan itu terjadi?)",
  ui_story_5087_50870501_28_dialog_content = "(Ketika aku melihat gadis kecil ini... kenapa tiba-tiba aku mengingat sang ratu?)",
  ui_story_5087_50870501_29_dialog_content = "... Nikinis! Hati-hati!",
  ui_story_5087_50870501_30_dialog_content = "Graaah!",
  ui_story_5087_50870501_31_dialog_content = "Dapatkan di belakangku, gadis kecil!",
  ui_story_5087_50870501_32_dialog_content = "Aku khawatir aku tidak bisa melakukan itu.",
  ui_story_5087_50870501_33_dialog_content = "Tidak peduli di mana saya berada, saya harus membantu keluarga saya dengan beban mereka.",
  ui_story_5087_50870502_1_dialog_content = "Kamu bisa menggunakan Luminatics?",
  ui_story_5087_50870502_2_dialog_content = "Dan dengan cekatan, pada saat itu...",
  ui_story_5087_50870502_3_dialog_content = "Ini hampir tidak biasa di sini di Northland.",
  ui_story_5087_50870502_4_dialog_content = "Kamu mencoba melindungiku tadi, 'kan? Terima kasih, silakan terima bunga-bunga ini sebagai tanda rasa terima kasihku. Selamat tinggal!",
  ui_story_5087_50870502_5_dialog_content = "Tunggu, kembali! Aku tidak bisa mengambil ini secara gratis... Setidaknya beri tahu saya nama Anda!",
  ui_story_5087_50870502_6_dialog_content = "Shaya. Nama saya adalah Shaya.",
  ui_story_5087_50870502_7_dialog_content = "Nikinis—",
  ui_story_5087_50870502_8_dialog_content = "Kamu baik-baik saja? Monster itu tidak melukaimu, 'kan? Dan dengan siapa kamu baru saja berbicara?",
  ui_story_5087_50870502_9_dialog_content = "Aku baik-baik saja, Nepolis. Aku bertemu seorang gadis kecil yang menjual bunga di hutan, dan dia memberiku sebuah buket karena telah membantunya. Lihat?",
  ui_story_5087_50870502_10_dialog_content = "Itu bagus karena mereka semua adalah bunga favoritmu.",
  ui_story_5087_50870502_11_dialog_content = "Kamu tidak pernah suka keramaian, dan kamu selalu menghindar dari Winter Palace saat ada pesta, bahkan yang diadakan untukmu...",
  ui_story_5087_50870502_12_dialog_content = "Tapi setiap kali, orang-orang yang kamu bantu akan menemukanmu dan memberikanmu bunga! Karangan bunga yang indah dari bunga narsis putih dan lili.",
  ui_story_5087_50870502_13_dialog_content = "Saya yakin gadis kecil itu juga... Hah?",
  ui_story_5087_50870502_14_dialog_content = "Bouquet ini hanya berisi bunga putih narcissus...",
  ui_story_5087_50870502_15_dialog_content = "!",
  ui_story_5087_50870502_16_dialog_content = "Ayo, Nikinis. Mari pastikan tidak ada lagi fragmen cermin di sekitar sini sebelum kita melapor kembali ke Winter Palace.",
  ui_story_5087_50870502_17_dialog_content = "(Apakah Nepolis... sedang cemberut? Itu aneh, aku rasa aku belum pernah melihat sisi ini darinya.)",
  ui_story_5087_50870502_18_dialog_content = "(Aku hanya akan menaruh salah satu bunga ini di rambutnya. Dengan begitu, bunga putih narcissus dan lili akan bersatu kembali.)",
  ui_story_5087_50870502_19_dialog_content = "Hmm? Ada sesuatu yang keras tersembunyi di dalam buket ini...",
  ui_story_5087_50870502_20_dialog_content = "Itu cermin tangan itu!",
  ui_story_5087_50870502_21_dialog_content = "(Apakah Shaya melakukan ini dengan sengaja? Apakah dia memasukkan cermin ini ke dalam buket karena aku menolak untuk membelinya?)",
  ui_story_5087_50870502_22_dialog_content = "(Mengapa dia begitu berniat untuk memberikan ini padaku?)",
  ui_story_5087_50870502_23_dialog_content = "Nikinis... Nikinis...",
  ui_story_5087_50870502_24_dialog_content = "(Dia lagi! Suara dari Cermin Northland! Dia bisa muncul di cermin lain juga?)",
  ui_story_5087_50870502_25_dialog_content = "(Ini buruk, aku berjanji pada Nepolis aku tidak akan mendekati cermin yang mencurigakan...)",
  ui_story_5087_50870502_26_dialog_content = "Nikinis... Bisakah kamu mendengarku?",
  ui_story_5087_50870502_27_dialog_content = "...",
  ui_story_5087_50870502_28_dialog_content = "Ya, tapi siapa kamu? Kenapa kamu terus muncul di dalam cermin?",
  ui_story_5087_50870502_29_dialog_content = "Bagus, cermin akhirnya berada di tanganmu... Tolong... Jangan beritahu siapa-siapa tentang ini!",
  ui_story_5087_50870600_1_dialog_content = "<color=#e8d9bb>Malam tiba, dan badai salju yang mengaum menutupi langit dengan salju. Bahkan bayangan api di dalam perapian tampak berkedip dengan gelisah.</color>",
  ui_story_5087_50870600_2_dialog_content = "(Kira-kira bagaimana orang tua kita bertahan dalam badai seperti ini... Pasti mereka tidak akan tinggal di luar pada malam seperti ini, kan?)",
  ui_story_5087_50870600_3_dialog_content = "Akhirnya, aku selesai melaporkan semua hal kepada Ratu, Nikinis! Dia sangat senang dengan hasil kerja kita!",
  ui_story_5087_50870600_4_dialog_content = "Itu luar biasa. Sekarang kita akhirnya bisa pulang dan menghabiskan waktu bersama orang tua kita.",
  ui_story_5087_50870600_5_dialog_content = "Oh... Benar...",
  ui_story_5087_50870600_6_dialog_content = "Nepolis! Nikinis! Oh, syukurlah kau belum pergi!",
  ui_story_5087_50870600_7_dialog_content = "Baru saja ada surat masuk dari orang tua Anda. Mereka mengatakan mereka masih menjalankan perintah sang Ratu, jadi mereka tidak akan bisa kembali selama beberapa hari lagi.",
  ui_story_5087_50870600_8_dialog_content = "Dalam badai seperti ini, lebih baik jika kamu tidak kembali sekarang juga. Tidak ingin terjebak di salju, bukan?",
  ui_story_5087_50870600_9_dialog_content = "T-tapi...",
  ui_story_5087_50870600_10_dialog_content = "Dia memiliki alasan, Nikinis. Mencoba menavigasi badai salju ini di malam hari akan sangat berbahaya.",
  ui_story_5087_50870600_11_dialog_content = "Lagipula, orang tua kita bahkan tidak di rumah sekarang. Mari kita menghabiskan malam di tempat yang dekat saja, oke?",
  ui_story_5087_50870600_12_dialog_content = "Baiklah...",
  ui_story_5087_50870600_13_dialog_content = "(Saya tidak ingat pernah melihat orang tua kita di Istana Musim Dingin sebelumnya... Apakah ini bisa jadi efek samping dari penyakitku?)",
  ui_story_5087_50870600_14_dialog_content = "(Jika mereka telah bekerja untuk ratu, tentunya Nepolis dan aku pasti telah melihat mereka di istana, bukan?)",
  ui_story_5087_50870600_15_dialog_content = "(Tapi, apakah mereka benar-benar menjalankan perintah sang Ratu? Kapan mereka mulai melakukan itu? Mengapa saya tidak ingat apa-apa tentang itu?)",
  ui_story_5087_50870600_16_dialog_content = "(Satu-satunya hal yang bisa saya ingat dengan jelas adalah mereka membawa kami ke Winter Palace untuk perawatan.)",
  ui_story_5087_50870600_17_dialog_content = "(Setelah itu, aku hampir tidak bisa mengingat wajah mereka...)",
  ui_story_5087_50870600_18_dialog_content = "(Bisakah penyakitku telah mempengaruhi ingatanku dengan cara tertentu?)",
  ui_story_5087_50870600_19_dialog_content = "(Meskipun aku tidak ingat tentang semua ini, Nepolis dan kurir itu berbicara tentangnya seperti hal yang sangat biasa. Rasanya hampir seperti...)",
  ui_story_5087_50870600_20_dialog_content = "(Dunia ini diselimuti oleh lapisan ilusi.)",
  ui_story_5087_50870600_21_dialog_content = "(Tidak... Pasti aku yang berhalusinasi. Adikku nyata, tidak ada keraguan tentang itu.)",
  ui_story_5087_50870600_22_dialog_content = "... Ah!",
  ui_story_5087_50870600_23_dialog_content = "Apa itu, Nepolis?",
  ui_story_5087_50870600_24_dialog_content = "Rambutku! Tersangkut di salah satu cabang pohon! Tolong aku, Nikinis!",
  ui_story_5087_50870600_25_dialog_content = "Sejujurnya... Bagaimana kamu bisa membuatnya tersangkut di cabang? Berhenti menggeliat-geliut sebelum kamu menyakiti diri sendiri!",
  ui_story_5087_50870600_26_dialog_content = "Ini karena aku baru saja melihat seekor tupai kecil yang lucu. Aku berjalan mendekat untuk melihat lebih dekat, tapi kemudian...",
  ui_story_5087_50870600_27_dialog_content = "Kamu berhasil melakukan beberapa hal yang cukup luar biasa ketika saya tidak memperhatikan, tahu?",
  ui_story_5087_50870600_28_dialog_content = "Kau ini, Nikinis. Akhir-akhir ini kau telah menemukan berbagai jenis kekuatan dan emosi, semua tanpa aku sadari...",
  ui_story_5087_50870600_29_dialog_content = "Kita dulu adalah satu dan sama, ingat? Hati dan jiwa kita terhubung, dan kita berbagi segalanya mulai dari penampilan dan bakat hingga suka dan tidak suka kita.",
  ui_story_5087_50870600_30_dialog_content = "Melihat kamu perlahan menjadi orang lain terkadang membuatku merasa sangat kesepian...",
  ui_story_5087_50870600_31_dialog_content = "Lihat buket yang kamu dapatkan—narcissus diikat erat dengan mawar kuning dan forget-me-not, tetapi tanpa ada lili...",
  ui_story_5087_50870600_32_dialog_content = "Nepolis... Apa yang sedang kamu bicarakan? Tidak ada pasangan saudara kandung di dunia ini yang lebih mirip daripada kita berdua! Kapan kita menjadi \"berbeda\" menurutmu?",
  ui_story_5087_50870600_33_dialog_content = "Aku berjanji tidak akan mendekati cermin itu lagi, jadi tolong jangan khawatir tentangku, oke?",
  ui_story_5087_50870600_34_dialog_content = "... Di sana! Rambutmu sudah tidak kusut lagi sekarang. Keluarlah dari bawah pohon itu.",
  ui_story_5087_50870600_35_dialog_content = "Manis, kebebasan manis!",
  ui_story_5087_50870600_36_dialog_content = "... Terima kasih, Nikinis. Tanpa kamu, saya tidak tahu harus berbuat apa.",
  ui_story_5087_50870600_37_dialog_content = "Jadi, berhentilah mengatakan hal-hal seperti \"Aku tidak membantu adikku...\"",
  ui_story_5087_50870600_38_dialog_content = "Memiliki kamu di sisiku adalah berkat terbesar yang pernah bisa aku minta.",
  ui_story_5087_50870600_39_dialog_content = "(Nepolis itu nyata, dan begitu juga aku. Tidak ada pertanyaan tentang itu.)",
  ui_story_5087_50870600_40_dialog_content = "(Itulah sebabnya... Aku harus menghancurkan cermin misterius ini.)",
  ui_story_5087_50870600_41_dialog_content = "Nikinis... Apakah itu kamu?",
  ui_story_5087_50870600_42_dialog_content = "(... Dia kembali lagi!)",
  ui_story_5087_50870600_43_dialog_content = "Tolong jangan bicara padaku lagi. Aku tidak ingin adikku terus menderita seperti ini!",
  ui_story_5087_50870600_44_dialog_content = "Cukup dengarkan aku, Nikinis! Kamu harus pergi... dan mencari... hanya kemudian...",
  ui_story_5087_50870600_45_dialog_content = "Pergi ke mana? Apa yang seharusnya aku temukan?",
  ui_story_5087_50870600_46_dialog_content = "Siapa kamu, dan mengapa kamu terus berbicara padaku melalui cermin?",
  ui_story_5087_50870600_47_dialog_content = "Aku... Kamu di dalam... Hanya dengan... kamu bisa...",
  ui_story_5087_50870600_48_dialog_content = "... Aku tidak mengerti apa-apa yang kamu katakan. Suaramu terus memudar di saat yang paling tidak tepat!",
  ui_story_5087_50870600_49_dialog_content = "Itu dia! Dia terus mengganggu kita! Bahkan setelah merusak... dia tidak pernah berhenti. Dia masih menghalangi... Urgh!",
  ui_story_5087_50870600_50_dialog_content = "\"Rusak\"? Apakah kamu berbicara tentang Northland Mirror? Apakah kamu tahu siapa yang melakukannya? Tunggu, bagaimana kamu tahu tentang cermin yang rusak?",
  ui_story_5087_50870600_51_dialog_content = "Bisa jadi... kamu lah yang mencuri Cermin Northland?",
  ui_story_5087_50870600_52_dialog_content = "<color=#e8d9bb>Sebelum orang di cermin bisa menjawab, badai salju menerpa lebih keras ke pondok, menggetarkan jendela di bingkainya.</color>",
  ui_story_5087_50870600_53_dialog_content = "<color=#e8d9bb>Nikinis menundukkan kepalanya sekali lagi. Cermin di tangannya hanya memantulkan nyala api yang berkedip dari perapian dan salju yang berputar di luar.</color>",
  ui_story_5087_50870700_1_dialog_content = "<color=#e8d9bb>Salju terus turun saat awan-awan gelap menggantung di Northland, penampilan mereka yang gelap dan serius mencerminkan suasana hati Nikinis.</color>",
  ui_story_5087_50870700_2_dialog_content = "<color=#e8d9bb>Rumah yang tak terjangkau, misteri yang tak terpecahkan, dan ingatan yang tidak pasti... Semua hal ini memberatkan hatinya.</color>",
  ui_story_5087_50870700_3_dialog_content = "<color=#e8d9bb>Satu-satunya kilauan harapan adalah cermin di tangannya, yang hampir dia hancurkan.</color>",
  ui_story_5087_50870700_4_dialog_content = "(Orang di dalam cermin sepertinya tidak akan kembali dalam waktu dekat...)",
  ui_story_5087_50870700_5_dialog_content = "(Apakah benar ada seseorang yang mengganggu komunikasi kita? Mungkin itu orang yang pertama kali merusak cermin itu.)",
  ui_story_5087_50870700_6_dialog_content = "(Orang dalam cermin ingin aku melakukan sesuatu... Tapi mengapa? Apakah mereka berkelahi dengan siapa pun yang memecahkan cermin? Pertanyaan-pertanyaan itu tampaknya tak pernah berakhir...)",
  ui_story_5087_50870700_7_dialog_content = "Nikinis! Kita mendapat masalah!",
  ui_story_5087_50870700_8_dialog_content = "A-Apa itu?",
  ui_story_5087_50870700_9_dialog_content = "Hah? Kenapa kamu terlihat begitu bingung? Jangan bilang kamu mendapatkan surat cinta atau semacamnya.",
  ui_story_5087_50870700_10_dialog_content = "Sama sekali tidak! Bahkan jika saya melakukannya, saya tidak akan menyembunyikannya darimu—",
  ui_story_5087_50870700_11_dialog_content = "Aku tidak akan pernah membiarkan kamu khawatir tentang hal seperti itu, Nepolis. Percayalah padaku.",
  ui_story_5087_50870700_12_dialog_content = "... Kamu tidak perlu membela dirimu seperti ini, tahu? Surat cinta kamu adalah urusanmu sendiri, setelah semua.",
  ui_story_5087_50870700_13_dialog_content = "Tidak ada surat cinta!",
  ui_story_5087_50870700_14_dialog_content = "O-Oke, aku percaya padamu! Sekarang dengarkan aku, sesuatu yang sangat besar baru saja terjadi—",
  ui_story_5087_50870700_15_dialog_content = "Ratu baru saja menerbitkan potret pencuri cermin!",
  ui_story_5087_50870700_16_dialog_content = "Apa? Di mana?",
  ui_story_5087_50870700_17_dialog_content = "Oh? Aku tidak mengira kamu akan begitu peduli tentang itu. Ikuti aku.",
  ui_story_5087_50870700_18_dialog_content = "Queen Bethlehem telah mengungkap identitas pencuri dan telah memposting potret mereka untuk semua orang lihat.",
  ui_story_5087_50870700_19_dialog_content = "Mulai hari ini, perbatasan Northland akan ditutup, dan pasukannya akan fokus pada penangkapan pencuri. Semua penduduk Northland dihimbau untuk melaporkan setiap aktivitas mencurigakan segera!",
  ui_story_5087_50870700_20_dialog_content = "Mereka menutup perbatasan? Yang Mulia Ratu jarang memobilisasi kerajaan seperti ini...",
  ui_story_5087_50870700_21_dialog_content = "Tidakkah kamu melihat apa yang terjadi pagi ini? Winter Palace hampir mengirimkan sebuah tentara untuk memburu pencuri ini!",
  ui_story_5087_50870700_22_dialog_content = "Bagiku masuk akal. Lagipula, tidak sembarang orang bisa menyelinap ke dalam gudang harta karun Winter Palace.",
  ui_story_5087_50870700_23_dialog_content = "Bahkan hanya satu potongan relik saja cukup kuat untuk meratakan seratus desa. Sang Ratu hanya melakukan ini demi kita semua.",
  ui_story_5087_50870700_24_dialog_content = "Lihatlah potret ini—ternyata pencurinya adalah seorang gadis kecil! Bagaimana seorang anak kecil bisa berhasil masuk ke Istana Musim Dingin?",
  ui_story_5087_50870700_25_dialog_content = "(Seorang gadis kecil? Jangan bilang...)",
  ui_story_5087_50870700_26_dialog_content = "Maafkan saya! Saya lewat—",
  ui_story_5087_50870700_27_dialog_content = "(Aku tahu itu... Itu dia!)",
  ui_story_5087_50870700_28_dialog_content = "Kamu juga terkejut, bukan Nikinis? Ternyata, pencuri yang paling dicari di Northland hanyalah seorang gadis kecil yang lucu...",
  ui_story_5087_50870700_29_dialog_content = "A-Aku harus pergi, Nepolis!",
  ui_story_5087_50870700_30_dialog_content = "Hah? Tunggu, Nikinis, ratu memberi kita misi lain—",
  ui_story_5087_50870700_31_dialog_content = "Hei! Apakah kamu di sana? Tolong katakan sesuatu!",
  ui_story_5087_50870700_32_dialog_content = "(Tidak ada respon... Bagaimana saya membuat orang di cermin muncul waktu itu? Benar! Itu ketika saya berpikir tentang menggunakan Luminatics untuk menghancurkannya!)",
  ui_story_5087_50870700_33_dialog_content = "(Saya akan mencoba menanamkan cermin dengan Lumina terlebih dahulu...)",
  ui_story_5087_50870700_34_dialog_content = "Nikinis!",
  ui_story_5087_50870700_35_dialog_content = "Kamu di sini! Katakan padaku, apakah kamu bekerja dengan gadis kecil bernama Shaya?",
  ui_story_5087_50870700_36_dialog_content = "Kalian berdua yang mencuri Cermin Northland, bukan?",
  ui_story_5087_50870700_37_dialog_content = "... Itu benar. Shaya sebenarnya... Karena dia... dan masuk... dengan sendirinya...",
  ui_story_5087_50870700_38_dialog_content = "Cermin Northland adalah jalan yang kami persiapkan untuk kamu... tapi itu rusak oleh...",
  ui_story_5087_50870700_39_dialog_content = "Harus dipulihkan terlebih dahulu... itulah mengapa kami membutuhkan bantuan Anda.",
  ui_story_5087_50870700_40_dialog_content = "Kami mengirim Shaya untuk mengantarkan cermin ini kepada kamu, sehingga kita bisa berkomunikasi.",
  ui_story_5087_50870700_41_dialog_content = "Apa yang kamu bicarakan? Beritahu aku apa yang kamu rencanakan!",
  ui_story_5087_50870700_42_dialog_content = "Aku tidak bisa menjawabmu sekarang. Setiap kali aku mencoba memberitahumu sesuatu... terhalang.",
  ui_story_5087_50870700_43_dialog_content = "Temukan Shaya, dan dia akan memberitahu kamu segalanya... Hanya dia yang bisa membantu kamu sekarang!",
  ui_story_5087_50870700_44_dialog_content = "<color=#e8d9bb>Orang dalam cermin menghilang dengan kilatan cahaya.</color>",
  ui_story_5087_50870700_45_dialog_content = "(Keputusan Yang Mulia Ratu ternyata tidak salah... Yang mencuri Northland Mirror adalah Shaya.)",
  ui_story_5087_50870700_46_dialog_content = "(Bukan hanya itu, dia dan orang di dalam cermin merencanakan sesuatu bersama.)",
  ui_story_5087_50870700_47_dialog_content = "(Tapi mengapa? Aku tidak merasakan kebencian dari Shaya atau cermin ini...)",
  ui_story_5087_50870700_48_dialog_content = "...",
  ui_story_5087_50870700_49_dialog_content = "(Aku akan menyembunyikan cermin untuk sekarang. Nepolis akan kembali setiap saat.)",
  ui_story_5087_50870700_50_dialog_content = "(Tidak bisa kubayangkan aku menyimpan rahasia besar darinya... Dengan mempercayai cermin, apakah aku semakin menjauhkan diri darinya?)",
  ui_story_5087_50870700_51_dialog_content = "Nikinis! Bagaimana bisa kamu kabur sendiri seperti itu?",
  ui_story_5087_50870700_52_dialog_content = "...Maafkan aku.",
  ui_story_5087_50870700_53_dialog_content = "Ratu telah memerintahkan kita untuk menangkap pencuri cermin! Tidak ada waktu untuk membuang-buang waktu, jadi ambil mantel dan sepatu botmu—",
  ui_story_5087_50870700_54_dialog_content = "Oh! Maaf, aku akan segera ke sana! Terima kasih sudah memberi tahu... Maaf karena tadi kabur.",
  ui_story_5087_50870700_55_dialog_content = "... Mengapa kamu minta maaf terus? Kita kan kakak beradik, ingat?",
  ui_story_5087_50870700_56_dialog_content = "Kamu adalah orang yang paling penting dalam hidupku. Apa pun yang terjadi, itu tidak akan pernah berubah.",
  ui_story_5087_50870800_1_dialog_content = "Aku akan periksa di sana, Nepolis.",
  ui_story_5087_50870800_2_dialog_content = "Maka aku akan melihat ke sini. Tetap berjaga-jaga.",
  ui_story_5087_50870800_3_dialog_content = "Aku akan baik-baik saja. Lagipula, aku tahu kamu akan datang menyelamatkanku segera setelah kamu merasakan bahwa aku dalam masalah.",
  ui_story_5087_50870800_4_dialog_content = "Sebagai kembar, kita terhubung dalam pikiran dan jiwa, ingat?",
  ui_story_5087_50870800_5_dialog_content = "...",
  ui_story_5087_50870800_6_dialog_content = "(Tempat ini seharusnya cukup aman.)",
  ui_story_5087_50870800_7_dialog_content = "Hai, kau di sana?",
  ui_story_5087_50870800_8_dialog_content = "Apa itu, Nikinis? Apakah kamu berhasil menemukan Shaya?",
  ui_story_5087_50870800_9_dialog_content = "Belum, tidak. Saya dan adik saya sedang mencarinya saat ini, bersama dengan seluruh kerajaan.",
  ui_story_5087_50870800_10_dialog_content = "Saya tidak bisa mengingat kapan seluruh Northland dikerahkan untuk mengejar satu pencuri saja. Sesuatu tentang dunia ini tampaknya tidak benar setelah semua...",
  ui_story_5087_50870800_11_dialog_content = "Itu karena kamu... Tapi jangan khawatir tentang Shaya. Lagipula, dia adalah... Orang biasa seharusnya tidak menjadi ancaman baginya.",
  ui_story_5087_50870800_12_dialog_content = "Dengarkan aku, cermin! Aku...",
  ui_story_5087_50870800_13_dialog_content = "Aku ingin memberitahu saudaraku semua yang aku tahu tentang kamu dan Shaya...",
  ui_story_5087_50870800_14_dialog_content = "Hah? A... Aku tidak tahu apakah itu ide yang bagus...",
  ui_story_5087_50870800_15_dialog_content = "Saya dan kakak saya adalah satu dan sama.",
  ui_story_5087_50870800_16_dialog_content = "Ha?",
  ui_story_5087_50870800_17_dialog_content = "Sejak kita datang ke dunia ini, kita selalu bersama. Seperti dua bunga yang ditanam berdampingan, kita tumbuh dan mekar dengan cara yang sama persis.",
  ui_story_5087_50870800_18_dialog_content = "Saya tidak bisa menjelaskan mengapa, tapi saya tahu kamu dan Shaya bukan orang jahat. Mungkin ini hanya intuisi saya...",
  ui_story_5087_50870800_19_dialog_content = "Dan jika itu benar, saudaraku akan memiliki intuisi yang sama seperti milikku. Tidak peduli apa yang kamu rencanakan, dia tidak akan menghalangi jalanmu.",
  ui_story_5087_50870800_20_dialog_content = "Faktanya, dia akan membantu Anda.",
  ui_story_5087_50870800_21_dialog_content = "... Apakah Anda benar-benar begitu yakin?",
  ui_story_5087_50870800_22_dialog_content = "Positif. Itu karena saya sudah mempertimbangkan hal yang sama.",
  ui_story_5087_50870800_23_dialog_content = "Saya hanya perlu melihat ke dalam hati saya sendiri untuk mengetahui apa pilihan saudara perempuan saya.",
  ui_story_5087_50870800_24_dialog_content = "... Aku mengerti.",
  ui_story_5087_50870800_25_dialog_content = "Saya punya satu permintaan lagi. Queen Bethlehem adalah orang yang memerintahkan penangkapan Shaya, yang berarti dia pasti tahu sesuatu.",
  ui_story_5087_50870800_26_dialog_content = "Apakah tidak apa-apa jika aku juga memberitahunya tentang—",
  ui_story_5087_50870800_27_dialog_content = "Tidak akan pernah!",
  ui_story_5087_50870800_28_dialog_content = "?",
  ui_story_5087_50870800_29_dialog_content = "Itu \"Queen Bethlehem\" adalah... Dia bukan... jadi kamu tidak bisa...",
  ui_story_5087_50870800_30_dialog_content = "Aku tidak bisa mendengar apa yang kamu katakan. Aku pikir gangguannya semakin parah.",
  ui_story_5087_50870800_31_dialog_content = "Urgh! Bagaimana aku bisa memberitahumu... Jangan percaya... Palsu!",
  ui_story_5087_50870800_32_dialog_content = "Apa yang palsu? Surat dari kurir itu? Cerita tentang orang tua saya? Kenangan saya?",
  ui_story_5087_50870800_33_dialog_content = "Atau mungkin... ratu?",
  ui_story_5087_50870800_34_dialog_content = "Baik!",
  ui_story_5087_50870800_35_dialog_content = "Yang Mulia adalah palsu?",
  ui_story_5087_50870800_36_dialog_content = "Ya! Itu benar! Dia... Tujuannya adalah...",
  ui_story_5087_50870800_37_dialog_content = "... Berhenti di sana!",
  ui_story_5087_50870800_38_dialog_content = "?",
  ui_story_5087_50870800_39_dialog_content = "Argh!",
  ui_story_5087_50870800_40_dialog_content = "Akhirnya aku menangkapmu! Mari kita lihat kamu kabur sekarang!",
  ui_story_5087_50870800_41_dialog_content = "Apa itu, Nepolis? Ah! Itu kamu... Shaya...",
  ui_story_5087_50870800_42_dialog_content = "Aku menangkap pencuri kecil yang licik ini menguntitmu dari pohon-pohon. Dia pasti sedang merencanakan sesuatu yang jahat!",
  ui_story_5087_50870800_43_dialog_content = "Tapi jangan khawatir, aku menangkapnya sebelum dia bisa bergerak! Sekarang kamu aman!",
  ui_story_5087_50870800_44_dialog_content = "...",
  ui_story_5087_50870800_45_dialog_content = "Nikinis... Tolong aku...",
  ui_story_5087_50870800_46_dialog_content = "Apa? K-Kalian saling kenal? Kapan itu terjadi? Dan kenapa saya tidak diberitahu tentang itu?",
  ui_story_5087_50870800_47_dialog_content = "Nepolis... Maafkan aku.",
  ui_story_5087_50870800_48_dialog_content = "Ah! Aku tak bermaksud menyalahkanmu—",
  ui_story_5087_50870800_49_dialog_content = "Tapi jangan khawatir, aku akan memberitahumu segalanya sekarang. Aku tidak akan menyembunyikan apapun darimu lagi, aku janji.",
  ui_story_5087_50870800_50_dialog_content = "Setelah ini... Aku akan membutuhkan kebijaksanaanmu.",
  ui_story_5087_50870900_1_dialog_content = "Queen Bethlehem adalah penipu?",
  ui_story_5087_50870900_2_dialog_content = "Ya. Dia hanyalah ilusi dari bayangan, itulah sebabnya reaksinya sangat agresif.",
  ui_story_5087_50870900_3_dialog_content = "Mengerahkan seluruh kerajaan untuk menangkap satu pencuri... adalah penggunaan kekuatan yang sangat tidak efisien.",
  ui_story_5087_50870900_4_dialog_content = "Ratu yang sebenarnya pasti akan memikirkan sesuatu yang jauh lebih cerdik.",
  ui_story_5087_50870900_5_dialog_content = "(Meski bertemu dengannya untuk kedua kalinya, aku masih merasa ada sesuatu yang unik tentang Shaya.)",
  ui_story_5087_50870900_6_dialog_content = "(Meskipun masih gadis kecil, dia memiliki aura yang benar, dan dia tidak ragu-ragu untuk mengkritik Ratu.)",
  ui_story_5087_50870900_7_dialog_content = "Memang benar bahwa metode Yang Mulia Ratu akhir-akhir ini agak berbeda, tetapi itu bukanlah alasan untuk meragukannya...",
  ui_story_5087_50870900_8_dialog_content = "Jika apa yang kamu katakan itu benar, Shaya, lalu di mana ratu yang sebenarnya?",
  ui_story_5087_50870900_9_dialog_content = "... Secara umum, Bethlehem cenderung menghabiskan waktunya di dunia yang berbeda—dunia di sisi lain Northland Mirror.",
  ui_story_5087_50870900_10_dialog_content = "... Kamu bilang ada dunia yang sepenuhnya berbeda di balik Cermin Northland?",
  ui_story_5087_50870900_11_dialog_content = "Apakah ini berarti alasanmu mencuri cermin adalah untuk pergi ke dunia lain dan menemukan Queen Bethlehem yang sebenarnya?",
  ui_story_5087_50870900_12_dialog_content = "Alasanmu di jalur yang benar... Itu benar, aku memang perlu pergi ke sana.",
  ui_story_5087_50870900_13_dialog_content = "Cermin Northland adalah jalan sempurna untuk bepergian antara kedua dunia.",
  ui_story_5087_50870900_14_dialog_content = "Tapi sekarang karena sudah rusak, harus diperbaiki sebelum saya bisa melakukannya.",
  ui_story_5087_50870900_15_dialog_content = "Nikinis, kamu memiliki afinitas yang kuat dengan Northland Mirror. Untuk mengembalikannya ke keadaan aslinya, saya membutuhkan bantuanmu.",
  ui_story_5087_50870900_16_dialog_content = "Apakah kamu bersedia membantu saya? Tentu saja, saya juga bersedia membantu kalian berdua.",
  ui_story_5087_50870900_17_dialog_content = "Orang dalam cermin bisa menjadi pemandumu. Dia juga ada di dunia lain, dan tujuannya tidak berbeda dengan milikku.",
  ui_story_5087_50870900_18_dialog_content = "...",
  ui_story_5087_50870900_19_dialog_content = "Apa pendapatmu, Nepolis? Aku tahu kamu tidak ingin aku mendekati cermin itu.",
  ui_story_5087_50870900_20_dialog_content = "Tapi, kau ingin melakukan ini, 'kan?",
  ui_story_5087_50870900_21_dialog_content = "Aku...",
  ui_story_5087_50870900_22_dialog_content = "... Maaf, Nikinis. Sepertinya rasa cemburuku membuatmu khawatir.",
  ui_story_5087_50870900_23_dialog_content = "Aku bisa merasakan bahwa kamu telah memikirkan tentang aku dan perasaanku beberapa hari ini...",
  ui_story_5087_50870900_24_dialog_content = "Meskipun aku yang lebih tua, aku jarang bertindak seperti itu.",
  ui_story_5087_50870900_25_dialog_content = "Itu sama sekali bukan masalahnya! Kita berpikir sama persis. Yang aku inginkan hanyalah bersamamu dalam pikiran dan jiwa, seperti biasanya...",
  ui_story_5087_50870900_26_dialog_content = "... Itulah yang paling kuinginkan di dunia ini!",
  ui_story_5087_50870900_27_dialog_content = "Tapi itu tidak memberiku hak untuk merenggut sayapmu.",
  ui_story_5087_50870900_28_dialog_content = "!",
  ui_story_5087_50870900_29_dialog_content = "...",
  ui_story_5087_50870900_30_dialog_content = "Sebenarnya, aku sangat sulit mempercayai semua yang baru saja kamu ceritakan kepada kami, Shaya.",
  ui_story_5087_50870900_31_dialog_content = "... Aku mengerti.",
  ui_story_5087_50870900_32_dialog_content = "Tapi, kakakku selalu memberikan nilai penting yang besar pada cermin itu.",
  ui_story_5087_50870900_33_dialog_content = "Setelah mendengar cerita ratu tentang bagaimana kita disembuhkan, saya yakin bahwa Nikinis dan cermin memiliki takdir yang tak terpisahkan.",
  ui_story_5087_50870900_34_dialog_content = "Aku merasa kesepian karena hanya saudaraku yang dipilih, dan jadi aku mulai bertindak karena iri...",
  ui_story_5087_50870900_35_dialog_content = "Salah jika aku melakukan itu. Sebagai kakak, seharusnya aku menjaganya dan membantunya tumbuh.",
  ui_story_5087_50870900_36_dialog_content = "Nepolis...",
  ui_story_5087_50870900_37_dialog_content = "... Kamu memiliki jiwa yang luar biasa, Nepolis.",
  ui_story_5087_50870900_38_dialog_content = "Mungkin selama ini aku telah meremehkanmu.",
  ui_story_5087_50870900_39_dialog_content = "Jadi, Shaya—",
  ui_story_5087_50870900_40_dialog_content = "Cukup beri tahu kami apa yang perlu kami lakukan untuk membantu kamu memulihkan Northland Mirror!",
  ui_story_5087_50871000_1_dialog_content = "...",
  ui_story_5087_50871000_2_dialog_content = "...",
  ui_story_5087_50871000_3_dialog_content = "Hmm... Setelah kita menyeberangi gunung ini, kita seharusnya sampai di Winter Palace.",
  ui_story_5087_50871000_4_dialog_content = "...",
  ui_story_5087_50871000_5_dialog_content = "...",
  ui_story_5087_50871000_6_dialog_content = "Kita tidak bisa terus berjalan dalam diam! Shaya, aku tahu kamu sangat tidak puas dengan ratu palsu sekarang—",
  ui_story_5087_50871000_7_dialog_content = "Saya sangat tidak puas, sebenarnya. Dia memobilisasi setiap prajurit di kerajaan untuk mencari seorang pencuri!",
  ui_story_5087_50871000_8_dialog_content = "Nepolis, aku tahu kamu masih belum yakin—",
  ui_story_5087_50871000_9_dialog_content = "Tentu saja aku tidak yakin!",
  ui_story_5087_50871000_10_dialog_content = "Satu hal untuk memulihkan Northland Mirror, atau menyelinap ke dalam gudang harta karun Winter Palace...",
  ui_story_5087_50871000_11_dialog_content = "Tapi \"bagaimana cara kita bergabung dan mengalahkan Ratu jika dia menemukan kita\"? Berani-beraninya kamu memasukkan itu dalam rencanamu!",
  ui_story_5087_50871000_12_dialog_content = "Kamu bahkan membuat gambar untuk ini!",
  ui_story_5087_50871000_13_dialog_content = "Bagaimana kamu bisa tahu kelemahan ratu dengan begitu baik, Shaya? Kamu yakin tidak ada rencana lain yang kamu sembunyikan?",
  ui_story_5087_50871000_14_dialog_content = "... Sekarang aku mengerti rasa sakit tidak bisa mengatakan yang sebenarnya.",
  ui_story_5087_50871000_15_dialog_content = "Nikinis! Apakah kamu tidak ingat risiko yang diambil oleh Yang Mulia Ratu untuk menyelamatkan nyawa kita?",
  ui_story_5087_50871000_16_dialog_content = "Aku...",
  ui_story_5087_50871000_17_dialog_content = "Bagaimana mungkin kamu bisa begitu mudah percaya setiap kata yang gadis ini katakan tentang queen kita yang merupakan penipu?",
  ui_story_5087_50871000_18_dialog_content = "Nepolis, aku menghargai kesetiaanmu kepada Bethlehem—",
  ui_story_5087_50871000_19_dialog_content = "Berhenti memanggil Ratu hanya dengan namanya saja!",
  ui_story_5087_50871000_20_dialog_content = "Tapi bahkan Bethlehem yang asli pun akan terkejut dengan kekerasan kepala Anda saat ini.",
  ui_story_5087_50871000_21_dialog_content = "Berani-beraninya kamu berkata seperti itu tentang Yang Mulia Ratu! Seorang ratu yang berwibawa dan mulia seperti dia tidak akan pernah—",
  ui_story_5087_50871000_22_dialog_content = "Dia akan. Percayalah padaku.",
  ui_story_5087_50871000_23_dialog_content = "Kalian berdua...",
  ui_story_5087_50871000_24_dialog_content = "Aku juga tidak tahu kenapa kamu begitu terburu-buru, Nikinis.",
  ui_story_5087_50871000_25_dialog_content = "Melinfiltrasi gudang harta karun membutuhkan perencanaan dan penyelidikan yang hati-hati. Lagipula, \"Northland Mirror\" tidak akan kemana-mana.",
  ui_story_5087_50871000_26_dialog_content = "Mengapa kau bersikeras masuk ke sana hari ini? Dan jika Ratu menemukan kita, apa kau benar-benar siap untuk bertarung dengannya?",
  ui_story_5087_50871000_27_dialog_content = "Itu bukan ratu milikmu.",
  ui_story_5087_50871000_28_dialog_content = "Hanya kamu satu-satunya yang mengatakan begitu.",
  ui_story_5087_50871000_29_dialog_content = "Sebagian besar tentara Winter Palace saat ini sedang mencari saya di seluruh negeri. Kita tidak akan mendapatkan kesempatan lain seperti ini untuk masuk ke ruang bawah tanah.",
  ui_story_5087_50871000_30_dialog_content = "Jadi kamu tahu kita juga \"mendobrak\", bukan?",
  ui_story_5087_50871000_31_dialog_content = "Nepolis! Shaya! Berhenti berdebat sekarang juga!",
  ui_story_5087_50871000_32_dialog_content = "Benar, saya sedang terburu-buru untuk melakukan ini. Tapi Nepolis, kamu harus mengerti bahwa ada sesuatu yang sangat salah dengan dunia ini sekarang...",
  ui_story_5087_50871000_33_dialog_content = "...",
  ui_story_5087_50871000_34_dialog_content = "Apa sebenarnya yang salah dengan itu?",
  ui_story_5087_50871000_35_dialog_content = "Banyak hal... Misalnya, kapan orang tua kita mulai bekerja untuk Winter Palace? Kamu dan setiap orang tampaknya tahu tentang itu, namun aku sama sekali tidak ingat tentang itu...",
  ui_story_5087_50871000_36_dialog_content = "Apa? Apakah ini bisa jadi efek samping dari penyakitmu? Apakah kamu merasa tidak enak badan lagi?",
  ui_story_5087_50871000_37_dialog_content = "Aku...",
  ui_story_5087_50871000_38_dialog_content = "(Apa yang harus saya lakukan? Untuk pertama kalinya dalam hidup saya... Saya tidak tahu bagaimana memberitahu saudara perempuan saya apa yang saya pikirkan.)",
  ui_story_5087_50871000_39_dialog_content = "(Dia tampak sangat khawatir tentangku. Apakah aku yang terlalu keras kepala tentang ini?)",
  ui_story_5087_50871000_40_dialog_content = "... Aku hanya senang kau baik-baik saja. Aku hanya... akan pergi mengintai dulu untuk sekarang.",
  ui_story_5087_50871000_41_dialog_content = "Tidak ada dari kalian yang salah, jadi tolong jangan biarkan itu mengganggu kalian. Hanya saja, hanya kamu yang mampu merasakan hal-hal tertentu.",
  ui_story_5087_50871000_42_dialog_content = "Tapi kenapa... Kenapa hanya aku yang bisa merasakan mereka?",
  ui_story_5087_50871000_43_dialog_content = "Saudariku dan aku selalu sama. Kapan kami... mulai memiliki perbedaan ini?",
  ui_story_5087_50871000_44_dialog_content = "Meskipun keduanya sama-sama murni dan putih seperti salju, lili dan white narcissus akan selalu menjadi dua bunga yang berbeda. Lebih jauh lagi...",
  ui_story_5087_50871000_45_dialog_content = "...",
  ui_story_5087_50871000_46_dialog_content = "Tolong beritahu aku, Shaya! Apakah ini hanya imajinasiku, atau memang ada yang salah dengan dunia ini?",
  ui_story_5087_50871000_47_dialog_content = "Selain ratu yang palsu, apakah ada hal lain yang tidak kamu beri tahu padaku?",
  ui_story_5087_50871000_48_dialog_content = "... Ada.",
  ui_story_5087_50871000_49_dialog_content = "!",
  ui_story_5087_50871000_50_dialog_content = "Tapi, akan tidak bijaksana jika saya memberitahu Anda sekarang.",
  ui_story_5087_50871000_51_dialog_content = "Setelah kita sampai di Winter Palace dan memulihkan cermin, semuanya akan menjadi jelas.",
  ui_story_5087_50871000_52_dialog_content = "Kamu... Kamu tidak punya saudari, bukan?",
  ui_story_5087_50871000_53_dialog_content = "... Ya.",
  ui_story_5087_50871000_54_dialog_content = "Serius?",
  ui_story_5087_50871000_55_dialog_content = "Meskipun dengan standar yang paling murah hati sekalipun, ini jauh dari yang bisa dianggap sebagai hubungan yang ramah.",
  ui_story_5087_50871000_56_dialog_content = "Jadi, aku benar-benar iri pada Nepolis dan kamu.",
  ui_story_5087_50871000_57_dialog_content = "... Aku ingin melindungi kalian berdua, meskipun hanya untuk detik lainnya.",
  ui_story_5087_50871000_58_dialog_content = "Kamu salah paham, Shaya.",
  ui_story_5087_50871000_59_dialog_content = "Ha?",
  ui_story_5087_50871000_60_dialog_content = "Meskipun saudariku dan aku dilahirkan dengan hubungan telepati yang memberi kami kesadaran tentang pikiran satu sama lain—",
  ui_story_5087_50871000_61_dialog_content = "Kami masih bertarung. Kamu sendiri yang melihatnya.",
  ui_story_5087_50871000_62_dialog_content = "!",
  ui_story_5087_50871000_63_dialog_content = "Tapi itu hanya sementara. Itu hanya sedikit gesekan yang muncul dari perbedaan perasaan dan pengalaman.",
  ui_story_5087_50871000_64_dialog_content = "Fakta bahwa kamu iri dengan hubungan kami adalah bukti bahwa kamu belum menyerah pada hubungan persaudaraanmu sendiri...",
  ui_story_5087_50871000_65_dialog_content = "Kamu masih bermimpi untuk memperbaiki hubungan dengan saudarimu.",
  ui_story_5087_50871000_66_dialog_content = "Selama kamu tidak menyerah, suatu hari nanti, kamu akan saling memahami... setidaknya itu yang saya percaya.",
  ui_story_5087_50871000_67_dialog_content = "... Terima kasih, Nikinis. Akan kuingat itu.",
  ui_story_5087_50871000_68_dialog_content = "Nepolis menolak untuk mengambil tindakan terhadap ratu palsu, jadi mari kita berpisah begitu kita berada di dalam Winter Palace.",
  ui_story_5087_50871000_69_dialog_content = "Aku akan mencari tahu cara menangani sang Ratu. Kamu hanya perlu menuju langsung ke ruang harta karun bersama kakakmu.",
  ui_story_5087_50871000_70_dialog_content = "Aku tidak bisa membiarkanmu melakukan itu! Yang Mulia Ratu terlalu kuat—",
  ui_story_5087_50871000_71_dialog_content = "Tidak, lebih baik seperti ini. Kita akan menonjol jika kita tetap bersatu.",
  ui_story_5087_50871000_72_dialog_content = "Dengan koneksi yang kalian berdua miliki, kalian menjadi pasangan yang jauh lebih efisien ketika kalian tidak menyeretku ikut serta.",
  ui_story_5087_50871000_73_dialog_content = "Aku akan sibukkan ratu secara diam-diam dan melindungimu. Lebih mudah melakukannya sendiri.",
  ui_story_5087_50871000_74_dialog_content = "Cari jawaban dari orang di cermin jika kamu menemui masalah selama operasi.",
  ui_story_5087_50871000_75_dialog_content = "... Dia adalah kawan yang paling kupercaya, dan dia akan menjadi pemandumu di Winter Palace.",
  ui_story_5087_50871101_1_dialog_content = "... Shaya berjalan di depan kami dan menyelinap ke dalam Istana Musim Dingin. Dia menyebutkan sesuatu tentang jalan rahasia yang hanya bisa dia masuki.",
  ui_story_5087_50871101_2_dialog_content = "Hahaha! Dia dalam bentuk anak kecil sekarang.",
  ui_story_5087_50871101_3_dialog_content = "?",
  ui_story_5087_50871101_4_dialog_content = "Sekarang, giliranmu. Keamanan selalu ketat di pintu masuk...",
  ui_story_5087_50871101_5_dialog_content = "Tapi kamu selalu masuk dan keluar dari Winter Palace, jadi tidak masalah, 'kan?",
  ui_story_5087_50871101_6_dialog_content = "...",
  ui_story_5087_50871101_7_dialog_content = "S-sepertinya begitu!",
  ui_story_5087_50871101_8_dialog_content = "Berhenti.",
  ui_story_5087_50871101_9_dialog_content = "Halo, saya Nikinis, dan ini adalah Nepolis. Kami memiliki urusan di Winter Palace—",
  ui_story_5087_50871101_10_dialog_content = "Masuk dilarang bagi publik sampai pencuri cermin ditangkap.",
  ui_story_5087_50871101_11_dialog_content = "(... Apa?)",
  ui_story_5087_50871101_12_dialog_content = "Kami bukan sembarang orang. Kami menemukan Cermin Northland yang dicuri.",
  ui_story_5087_50871101_13_dialog_content = "Kami berada di bawah perintah Yang Mulia Ratu untuk mengejar pencuri, dan kami baru saja menemukan petunjuk yang memerlukan pengecekan silang di perpustakaan istana.",
  ui_story_5087_50871101_14_dialog_content = "Bisakah kamu membiarkan kami lewat? Kita semua di sini melayani Yang Mulia Ratu.",
  ui_story_5087_50871101_15_dialog_content = "Oh... Hmm...",
  ui_story_5087_50871101_16_dialog_content = "Bantuanmu tentu akan dibalas. Aku akan datang dengan teh pilihan yang diberikan oleh Yang Mulia Ratu, dan kita bisa menikmatinya bersama!",
  ui_story_5087_50871101_17_dialog_content = "Benarkah? Ahem... Setelah dipikirkan lagi, kamu sangat terkait dengan pencurian dan harus diizinkan masuk.",
  ui_story_5087_50871101_18_dialog_content = "Kamu boleh lewat.",
  ui_story_5087_50871101_19_dialog_content = "(Itu berhasil!)",
  ui_story_5087_50871101_20_dialog_content = "... Belok kanan ke depan, terus lurus, lalu turun tangga.",
  ui_story_5087_50871101_21_dialog_content = "Tetap buka mata Anda. Zarya sering duduk di jendela bay di sana untuk menikmati pemandangan. Jangan biarkan dia menangkapmu.",
  ui_story_5087_50871101_22_dialog_content = "Zarya? Siapa itu? Yah, aku sudah melihat, dan tidak ada orang di sana.",
  ui_story_5087_50871101_23_dialog_content = "Apakah Zarya belum muncul di dunia lain? Oh, saya sudah bicara terlalu banyak... Ah! Turun! Kelinci-kelinci Novio pasti bersembunyi di halaman luar itu!",
  ui_story_5087_50871101_24_dialog_content = "Perhatikan juga saat turun tangga. Saya hampir saja dikirim enam kaki ke bawah oleh lembaran es yang ditinggalkan Noah...",
  ui_story_5087_50871101_25_dialog_content = "Sungguh, siapa sebenarnya kamu? Kamu bertindak sangat rahasia, namun kamu memiliki pengetahuan luas tentang struktur dan personel Winter Palace... Kamu yakin kamu bukan mata-mata?",
  ui_story_5087_50871101_26_dialog_content = "Percayalah padaku, aku orang baik!",
  ui_story_5087_50871101_27_dialog_content = "... Semuanya akan terungkap setelah cermin diperbaiki.",
  ui_story_5087_50871101_28_dialog_content = "... Hmm.",
  ui_story_5087_50871101_29_dialog_content = "Yah, kita sudah sampai sejauh ini, jadi mari kita percaya padanya dan Shaya.",
  ui_story_5087_50871101_30_dialog_content = "Berbicara tentang itu, kami tidak akan bisa sampai di sini tanpamu. Jika aku sendirian, aku bahkan tidak akan bisa masuk.",
  ui_story_5087_50871101_31_dialog_content = "Kamu khawatir tentang perasaanku lagi, bukan?",
  ui_story_5087_50871101_32_dialog_content = "Tidak, tidak ada!",
  ui_story_5087_50871101_33_dialog_content = "Aku bisa merasakan perasaanmu, ingat?",
  ui_story_5087_50871101_34_dialog_content = "...",
  ui_story_5087_50871101_35_dialog_content = "Nikinis, ingat gangguan ingatan yang kamu sebutkan? Apakah kamu yakin itu bukan efek samping dari penyakitmu?",
  ui_story_5087_50871101_36_dialog_content = "Sejujurnya... aku tidak tahu, tapi sesuatu memberitahuku bahwa ada lebih dari yang tampak oleh mata.",
  ui_story_5087_50871101_37_dialog_content = "Nah, mari kita selesaikan semua misteri. Apa pun yang kamu lakukan, aku akan selalu ada di sampingmu.",
  ui_story_5087_50871101_38_dialog_content = "... Maaf karena selalu menyeretmu ke dalam hal-hal ini...",
  ui_story_5087_50871101_39_dialog_content = "Sama sekali tidak. Saya sampai pada keputusan ini setelah banyak pertimbangan.",
  ui_story_5087_50871101_40_dialog_content = "Aku banyak berpikir dalam perjalanan kami ke Winter Palace. Aku memikirkan tentang masa lalu dan peristiwa-peristiwa baru-baru ini...",
  ui_story_5087_50871101_41_dialog_content = "Saya menyadari bahwa mungkin sejak awal kita memang tidak begitu mirip.",
  ui_story_5087_50871101_42_dialog_content = "!",
  ui_story_5087_50871101_43_dialog_content = "Saya lebih suka suasana yang hidup, namun kamu lebih suka ketenangan dan kesunyian. Saya suka hewan kecil, tetapi kamu lebih suka membaca...",
  ui_story_5087_50871101_44_dialog_content = "Saya bisa membuat pengawal kerajaan bergerak menjauh untuk kita, tetapi kamu tidak bisa melakukan hal yang sama.",
  ui_story_5087_50871101_45_dialog_content = "Hah? A-Aku akan mengambil semua yang kamu tunjukkan padaku...",
  ui_story_5087_50871101_46_dialog_content = "Hehe... Tidak apa-apa. Rasanya cukup menyenangkan tahu ada hal-hal yang hanya bisa aku capai.",
  ui_story_5087_50871101_47_dialog_content = "Saya yakin kita akan terlibat dalam lebih banyak argumen di masa depan, karena kita memang tidak sama. Mustahil bagi kita untuk selalu sependapat.",
  ui_story_5087_50871101_48_dialog_content = "Tapi itu bukan masalah besar, bahkan jika suatu hari hubungan yang kita miliki menghilang.",
  ui_story_5087_50871101_49_dialog_content = "Selama aku memiliki mulut untuk mencari pikiranmu dan sepasang kaki untuk mendekatimu...",
  ui_story_5087_50871101_50_dialog_content = "Hati kita tak akan pernah terpisah.",
  ui_story_5087_50871101_51_dialog_content = "Nepolis! Oh... Aku sangat senang mengetahui kau merasa seperti itu...",
  ui_story_5087_50871101_52_dialog_content = "Kamu yang terbaik! Aku tidak akan pernah meninggalkanmu! Huu-huu...",
  ui_story_5087_50871101_53_dialog_content = "Hei! Bersikaplah sesuai umurmu! Kita berada di Winter Palace...",
  ui_story_5087_50871101_54_dialog_content = "S-Sebenarnya, aku baru saja memiliki percakapan serupa dengan Shaya... Tunggu sebentar! Apakah kamu mendengar percakapan kami?",
  ui_story_5087_50871101_55_dialog_content = "Percakapan apa?",
  ui_story_5087_50871101_56_dialog_content = "Maaf mengganggu, tapi saya merasakan sesuatu yang kuat menekan saya... Cermin Northland ada di dekat sini.",
  ui_story_5087_50871101_57_dialog_content = "Bahaya mungkin mengintai di depan, dan saya mungkin tidak bisa memberi Anda petunjuk lebih lanjut kapan saja—",
  ui_story_5087_50871101_58_dialog_content = "... Tidak apa-apa.",
  ui_story_5087_50871101_59_dialog_content = "Jadi, ini adalah gudang harta Istana Musim Dingin—Ruang Relik.",
  ui_story_5087_50871101_60_dialog_content = "Hah? Apakah kamu pernah ke sini sebelumnya?",
  ui_story_5087_50871101_61_dialog_content = "Sister dan saya biasa bermain petak umpet di sini ketika kami kecil. Apakah kamu masih ingat waktu kami menerima perawatan di Istana Musim Dingin, Nepolis?",
  ui_story_5087_50871101_62_dialog_content = "...",
  ui_story_5087_50871101_63_dialog_content = "Nepolis?",
  ui_story_5087_50871101_64_dialog_content = "Mereka... datang.",
  ui_story_5087_50871101_65_dialog_content = "Graah!",
  ui_story_5087_50871102_1_dialog_content = "Huff... Huff... Ini beberapa monster yang kuat. Apa yang mereka lakukan di Winter Palace?",
  ui_story_5087_50871102_2_dialog_content = "Kita akan mencari tahu nanti. Masuk ke Ruang Relik! Cepat!",
  ui_story_5087_50871102_3_dialog_content = "Cermin Northland! Aku tahu aku akan menemukanmu di sini...",
  ui_story_5087_50871102_4_dialog_content = "<color=#e8d9bb>Cermin Northland tampak rusak, dengan retakan dan celah di seluruh permukaannya.</color>",
  ui_story_5087_50871102_5_dialog_content = "<color=#e8d9bb>Namun, cermin itu masih memancarkan cahaya yang lembut dan halus sementara bayangan-bayangan tak terhitung jumlahnya berkedip di permukaan cermin yang retak.</color>",
  ui_story_5087_50871102_6_dialog_content = "(Sosok-sosok itu memberikan saya perasaan yang sangat akrab...)",
  ui_story_5087_50871102_7_dialog_content = "C-Cermin itu! Apakah kamu Lady Nikinis?",
  ui_story_5087_50871102_8_dialog_content = "Tenanglah. Saya adalah Nikinis, dan saya di sini atas perintah Queen Bethlehem.",
  ui_story_5087_50871102_9_dialog_content = "Saya curiga relik kuno adalah sumber dari serangkaian peristiwa aneh yang baru-baru ini kamu alami.",
  ui_story_5087_50871102_10_dialog_content = "Karena ini adalah masalah yang sangat penting, saya meminta Anda untuk memberi tahu saya setiap detailnya.",
  ui_story_5087_50871102_11_dialog_content = "Tentu saja!",
  ui_story_5087_50871102_12_dialog_content = "Graaah!",
  ui_story_5087_50871102_13_dialog_content = "Monster menjijikkan... A-Aku akan mengalahkanmu!",
  ui_story_5087_50871102_14_dialog_content = "Monster, pergi.",
  ui_story_5087_50871102_15_dialog_content = "Graaah...",
  ui_story_5087_50871102_16_dialog_content = "Lady Nikinis! T-Terima kasih telah menyelamatkan saya!",
  ui_story_5087_50871102_17_dialog_content = "Hidupmu adalah hal yang murni dan berharga. Lain kali, sebut namaku sebelum mempertaruhkan hidupmu dalam pertempuran.",
  ui_story_5087_50871102_18_dialog_content = "Aku menyelinap keluar dari pesta perayaan lagi... Setiap orang pasti berpikir aku sombong dan menjengkelkan.",
  ui_story_5087_50871102_19_dialog_content = "Tapi, aku benar-benar tidak tahu bagaimana harus bersikap di sana. Semua orang tampak begitu bahagia, dan hanya aku...",
  ui_story_5087_50871102_20_dialog_content = "Lady Nikinis!",
  ui_story_5087_50871102_21_dialog_content = "Kamu dari masa itu—",
  ui_story_5087_50871102_22_dialog_content = "Aku melihatmu pergi diam-diam, t-tapi aku belum sempat memberikan ini padamu!",
  ui_story_5087_50871102_23_dialog_content = "Sebuah buket bunga narcissus dan lili...",
  ui_story_5087_50871102_24_dialog_content = "Aku dengar bunga-bunga itu adalah bunga favoritmu.",
  ui_story_5087_50871102_25_dialog_content = "Lady Nikinis, saya tidak bisa cukup berterima kasih karena selalu berjuang di sisi kami dan melindungi kami!",
  ui_story_5087_50871102_26_dialog_content = "(Apakah itu... ingatanku tadi?)",
  ui_story_5087_50871102_27_dialog_content = "(Apakah aku pernah begitu mengagumkan dan tenang? Apakah aku pernah berpartisipasi dalam banyak peristiwa penting?)",
  ui_story_5087_50871102_28_dialog_content = "<color=#e8d9bb>Seolah-olah ditarik oleh ingatannya yang telah pulih, Nikinis melangkah maju menuju Northland Mirror dan meletakkan telapak tangannya di atasnya—</color>",
  ui_story_5087_50871102_29_dialog_content = "Ini utuh lagi! ... Kamu benar-benar memiliki hubungan khusus dengannya, Nikinis.",
  ui_story_5087_50871102_30_dialog_content = "Anu...",
  ui_story_5087_50871102_31_dialog_content = "Ini bagus. Sekarang, hanya tinggal satu langkah terakhir!",
  ui_story_5087_50871102_32_dialog_content = "Langkah terakhir? Bukankah kamu bilang bahwa segalanya akan terungkap setelah cermin itu diperbaiki?",
  ui_story_5087_50871102_33_dialog_content = "Nikinis, kamu seharusnya telah berhasil mengambil kembali sebagian dari ingatanmu saat memperbaiki cermin.",
  ui_story_5087_50871102_34_dialog_content = "Sekarang... Yang tersisa hanyalah untuk <color=#FFB400>melewati cermin</color>!",
  ui_story_5087_50871102_35_dialog_content = "Apa? Melewati ke dunia lain?",
  ui_story_5087_50871102_36_dialog_content = "Tepat sekali. Itulah tempat sebenarnya Queen Bethlehem berada. Kenangan-kenangan yang tersisa dan jawaban yang kamu cari juga ada di balik cermin!",
  ui_story_5087_50871102_37_dialog_content = "aku tidak tahu...",
  ui_story_5087_50871102_38_dialog_content = "Lakukan itu, Nikinis.",
  ui_story_5087_50871102_39_dialog_content = "Hah? Kamu ingin aku masuk ke dalam cermin?",
  ui_story_5087_50871102_40_dialog_content = "Benar. Kita sudah sampai sejauh ini. Kita tidak bisa hanya berbalik dan pulang, bukan?",
  ui_story_5087_50871102_41_dialog_content = "Kamu harus mendapatkan kembali ingatanmu, memahami semuanya, dan kembali untuk menceritakan setiap detail kepadaku.",
  ui_story_5087_50871102_42_dialog_content = "Jika cermin itu berani menghentikanmu, aku tidak akan beristirahat sampai aku membawamu kembali, dan kita akan menunjukkan siapa Bos sebenarnya!",
  ui_story_5087_50871102_43_dialog_content = "Jadi, lakukan saja. Itu janji.",
  ui_story_5087_50871102_44_dialog_content = "Nepolis...",
  ui_story_5087_50871102_45_dialog_content = "...",
  ui_story_5087_50871102_46_dialog_content = "Ayo, Nikinis.",
  ui_story_5087_50871102_47_dialog_content = "A-Aku akan pergi kalau begitu, Nepolis!",
  ui_story_5087_50871102_48_dialog_content = "Baik.",
  ui_story_5087_50871102_49_dialog_content = "<color=#e8d9bb>Cermin itu berkilau lebih terang seolah-olah menyambut Nikinis, dan akhirnya dia mengambil langkah itu—</color>",
  ui_story_5087_50871102_50_dialog_content = "<color=#e8d9bb>Mendesis.</color>",
  ui_story_5087_50871102_51_dialog_content = "Uh... Argh! Jangan... berpikir tentang hal itu!",
  ui_story_5087_50871102_52_dialog_content = "Ada apa, Nepolis?",
  ui_story_5087_50871102_53_dialog_content = "Aku... baik-baik saja... Cepat... Aduhhh!",
  ui_story_5087_50871102_54_dialog_content = "...",
  ui_story_5087_50871102_55_dialog_content = "Nepolis! Nepolis! Kamu baik-baik saja?",
  ui_story_5087_50871102_56_dialog_content = "Nikinis! Jangan dekat-dekat dengan adikmu! Aku takut dia—",
  ui_story_5087_50871102_57_dialog_content = "... Nikinis.",
  ui_story_5087_50871102_58_dialog_content = "Aku di sini! Bagaimana perasaanmu? Ada bagian tubuhmu yang terasa sakit?",
  ui_story_5087_50871102_59_dialog_content = "Sisi lain cermin... sangat berbahaya.",
  ui_story_5087_50871102_60_dialog_content = "Ha?",
  ui_story_5087_50871102_61_dialog_content = "Aku tidak bisa membiarkanmu pergi ke tempat yang begitu berbahaya. Cukup tetap di sisiku, oke?",
  ui_story_5087_50871102_62_dialog_content = "T-Tapi... Kamu barusan bilang...",
  ui_story_5087_50871102_63_dialog_content = "Aku takut... Aku takut kehilanganmu... Begitu kau melewati cermin, aku tak akan pernah melihatmu lagi.",
  ui_story_5087_50871102_64_dialog_content = "Yang aku butuhkan hanya kamu, dan aku pikir kamu juga merasakan hal yang sama, benar?",
  ui_story_5087_50871102_65_dialog_content = "Kamu akan sangat kesepian tanpa aku... Kamu bahkan tidak akan mampu menghadapi senyuman orang-orang di pesta.",
  ui_story_5087_50871102_66_dialog_content = "!",
  ui_story_5087_50871102_67_dialog_content = "Semakin bahagia orang lain, semakin menyakitkan bagi kamu. Karena dalam hati, kamu tahu bahwa kebahagiaanmu tak akan pernah kembali...",
  ui_story_5087_50871102_68_dialog_content = "Tetaplah bersamaku, saudariku... Nikinisku—",
  ui_story_5087_50871102_69_dialog_content = "Nikinis, jangan biarkan dia menipumu. Itu bukan lagi kakakmu!",
  ui_story_5087_50871102_70_dialog_content = "Kamu harus melewati cermin! Kamu berada di dalam <color=#FFB400>dunia cermin</color> yang diciptakan oleh Cermin Northland! Dan sisi ini—",
  ui_story_5087_50871102_71_dialog_content = "Inilah tempat <color=#FFB400>kenyataan</color> sejati berada!",
  ui_story_5087_50871102_72_dialog_content = "!",
  ui_story_5087_50871102_73_dialog_content = "Apakah kamu tidak memperhatikan? Tidak ada yang benar di dunia ini!",
  ui_story_5087_50871102_74_dialog_content = "Ada yang tidak beres... Ya, saya tidak ingat orang tua saya pernah bekerja di Winter Palace...",
  ui_story_5087_50871102_75_dialog_content = "Karena itu dibuat oleh Northland Mirror!",
  ui_story_5087_50871102_76_dialog_content = "Winter Palace terlalu bersih...",
  ui_story_5087_50871102_77_dialog_content = "Karena tidak ada bayangan! Semuanya di sini adalah ilusi tanpa bayangan yang diciptakan oleh cermin! Bahkan ratu pun adalah ilusi!",
  ui_story_5087_50871102_78_dialog_content = "Itu benar! Lilin dan furnitur tidak memiliki bayangan, tapi aku punya! Dan Nepolis...",
  ui_story_5087_50871102_79_dialog_content = "... Tunggu! Kamu salah! Nepolis memiliki bayangan! Dia nyata!",
  ui_story_5087_50871102_80_dialog_content = "... Apakah Shaya belum datang juga? Dia akan menjelaskan semuanya kepada kamu! Pada titik ini, saya kira saya bisa memberi tahu kamu kebenarannya. Shaya adalah Beth—",
  ui_story_5087_50871102_81_dialog_content = "Dia tidak datang.",
  ui_story_5087_50871102_82_dialog_content = "Kau—",
  ui_story_5087_50871102_83_dialog_content = "<color=#e8d9bb>Nikinis secara insting melirik ke kaki ratu. Tidak ada apa-apa di sana, juga tidak ada apa-apa di kaki pengawal kerajaan.</color>",
  ui_story_5087_50871102_84_dialog_content = "<color=#e8d9bb>Tidak ada! Tidak ada apa-apa di sana! Tak satu pun dari mereka yang memiliki bayangan!</color>",
  ui_story_5087_50871102_85_dialog_content = "<color=#e8d9bb>\"Ratu\" membekukan Cermin Northland dengan sekali lambaian telapak tangannya, dan dengan lambaian lain, cermin itu terbang dan hancur menjadi serpihan.</color>",
  ui_story_5087_50871102_86_dialog_content = "... Jadi kamu ini palsu!",
  ui_story_5087_50871102_87_dialog_content = "Saya bukan satu-satunya. Tunjukkan dirimu, setiap orang.",
  ui_story_5087_50871102_88_dialog_content = "Graaah!",
  ui_story_5087_50871102_89_dialog_content = "Jangan berani coba-coba, ya! Tak akan kubiarkan kalian menyakiti Nepolis—",
  ui_story_5087_50871102_90_dialog_content = "Nepolis? Heh, kau memverifikasi bayanganku, tapi kau tidak melakukan hal yang sama untuknya?",
  ui_story_5087_50871102_91_dialog_content = "Tidak... Dia berbeda...",
  ui_story_5087_50871102_92_dialog_content = "Graah! Graaah!",
  ui_story_5087_50871102_93_dialog_content = "Mengapa saya harus memalsukan kehidupan orang tua Anda? Karena mereka hanya hidup di dunia ini!",
  ui_story_5087_50871102_94_dialog_content = "Sama seperti Nepolis.",
  ui_story_5087_50871102_95_dialog_content = "Tidak... Hentikan!",
  ui_story_5087_50871102_96_dialog_content = "... Astaga, kita sudah saling kenal begitu lama. Saya pikir kamu lebih pintar dari ini.",
  ui_story_5087_50871102_97_dialog_content = "Baiklah, aku akan menangkapmu terlebih dahulu, lalu perlahan membuatmu menghadapi kenyataan.",
  ui_story_5087_50871102_98_dialog_content = "Dapatkan dia! Tidak masalah jika kamu sedikit kasar!",
  ui_story_5087_50871102_99_dialog_content = "Graaah!",
  ui_story_5087_50871102_100_dialog_content = "<color=#e8d9bb>Urgh! Pukulan terberat tidak mendarat di Nikinis.</color>",
  ui_story_5087_50871102_101_dialog_content = "N-Nepolis?",
  ui_story_5087_50871102_102_dialog_content = "<color=#e8d9bb>Nikinis memperhatikan sesuatu yang gelap dan tidak jelas mengalir keluar dari luka Nepolis—</color>",
  ui_story_5087_50871102_103_dialog_content = "<color=#e8d9bb>Dan kemudian, dia mulai meleleh di tempat.</color>",
  ui_story_5087_50871102_104_dialog_content = "Tidak... Ini tidak nyata... Nepolis... Nepolis!",
  ui_story_5087_50871102_105_dialog_content = "N-Nikinis...",
  ui_story_5087_50871102_106_dialog_content = "Nepolis... Tidak! Tidak... Tolong jangan pergi—",
  ui_story_5087_50871102_107_dialog_content = "L-Lari!",
  ui_story_5087_50871102_108_dialog_content = "!",
  ui_story_5087_50871102_109_dialog_content = "<color=#e8d9bb>Monster tak terhitung jumlahnya berlari maju dan menyapu sosok bayangan Nepolis.</color>",
  ui_story_5087_50871102_110_dialog_content = "TIDAK! Ke mana kamu pergi, Nepolis?",
  ui_story_5087_50871102_111_dialog_content = "<color=#e8d9bb>Nikinis meraih dengan panik, tetapi yang tersisa hanyalah semburan kabut gelap yang menguap dalam genggamannya.</color>",
  ui_story_5087_50871102_112_dialog_content = "Nepolis... Nepolis...",
  ui_story_5087_50871102_113_dialog_content = "Graaaaaah!",
  ui_story_5087_50871102_114_dialog_content = "...",
  ui_story_5087_50871102_115_dialog_content = "Ini semua salahmu! Kamu monster!",
  ui_story_5087_50871102_116_dialog_content = "Graah...",
  ui_story_5087_50871102_117_dialog_content = "Kamu mendapatkan kembali sebagian kekuatanmu dari kenyataan?",
  ui_story_5087_50871102_118_dialog_content = "Nepolis, di mana kamu? Tolong jangan menakutiku seperti ini... Oh, kamu sudah pergi lebih dulu untuk membuka jalan untukku, kan? Dasar, kamu harusnya memberitahuku...",
  ui_story_5087_50871102_119_dialog_content = "Saya sedang dalam perjalanan ke kamu!",
  ui_story_5087_50871102_120_dialog_content = "Nepolis—",
  ui_story_5087_50871102_121_dialog_content = "Nepolis...",
  ui_story_5087_50871102_122_dialog_content = "Nepolis, di mana kamu? Aku memohon padamu! Tolong kembali padaku...",
  ui_story_5087_50871102_123_dialog_content = "<color=#e8d9bb>Tanpa disadari, Nikinis tiba di pondok tempat dia menemukan Northland Mirror bersama Nepolis.</color>",
  ui_story_5087_50871102_124_dialog_content = "Nepolis, apakah kamu kemari untuk menungguku?",
  ui_story_5087_50871102_125_dialog_content = "<color=#e8d9bb>Di tengah aroma bunga yang mempesona, bunga putih murni yang dibuat dari Luminatics tetap mekar sepenuhnya di dalam pondok.</color>",
  ui_story_5087_50871102_126_dialog_content = "<color=#e8d9bb>Tapi hanya white narcissuses yang tersisa. Setiap satu dari mereka adalah white narcissus.</color>",
  ui_story_5087_50871102_127_dialog_content = "<color=#e8d9bb>Semua bunga lili hilang, seolah-olah mereka tidak pernah ada sejak awal.</color>",
  ui_story_5087_50871102_128_dialog_content = "N-Nepolis?",
  ui_story_5087_50871102_129_dialog_content = "\"Dapatkah kamu mengingat bunga putih yang indah itu? Dua batang tumbuh dalam harmoni di tepi danau yang tenang.\"",
  ui_story_5087_50871102_130_dialog_content = "Tidak, tidak, tidak...",
  ui_story_5087_50871102_131_dialog_content = "\"Di bawah salju abu-abu yang turun, lili murni itu segera terkubur.\"",
  ui_story_5087_50871102_132_dialog_content = "\"Ditinggalkan sendirian di dunia, White Narcissus menangis dengan hening.\"",
  ui_story_5087_50871102_133_dialog_content = "... Waaaaaaaaaaaaaaaaaaaah!",
  ui_story_5087_50871200_1_dialog_content = "Aneh sekali.",
  ui_story_5087_50871200_2_dialog_content = "Ibu dan ayah bilang dia sudah pergi, tapi Nepolis selalu ada di sisiku.",
  ui_story_5087_50871200_3_dialog_content = "<color=#e8d9bb>Ngungg... Lalat mendarat pada daging merah yang perlahan kehilangan bentuknya.</color>",
  ui_story_5087_50871200_4_dialog_content = "Bau itu... Ah! Apakah itu rebusan apel dari minggu lalu? Apa yang sedang dilakukan di sana, Nikinis?",
  ui_story_5087_50871200_5_dialog_content = "Meski kamu tidak mau memakannya, setidaknya buanglah sisa makanannya! Lihat saja itu...",
  ui_story_5087_50871200_6_dialog_content = "Tapi... Itu bagian Nepolis.",
  ui_story_5087_50871200_7_dialog_content = "!",
  ui_story_5087_50871200_8_dialog_content = "Aneh sekali. Kenapa Nepolis tidak mau memakannya? Sup apel adalah favoritnya.",
  ui_story_5087_50871200_9_dialog_content = "Aku tahu! Dia pasti sedang tidak nafsu makan belakangan ini! Dia bahkan berbicara lebih sedikit sekarang... Apakah ini efek samping dari penyakitnya?",
  ui_story_5087_50871200_10_dialog_content = "Ketemu! Sekarang, siapa berikutnya?",
  ui_story_5087_50871200_11_dialog_content = "Hai! Izinkan kami bergabung dengan kalian!",
  ui_story_5087_50871200_12_dialog_content = "Hah? Tapi kamu sendirian.",
  ui_story_5087_50871200_13_dialog_content = "Apa maksudmu? Kakakku ada di sampingku! Dia jarang bicara akhir-akhir ini, tapi aku tahu dia ingin bermain bersama setiap orang!",
  ui_story_5087_50871200_14_dialog_content = "Luminatics kami terhubung, jadi saya tahu semua yang dia pikirkan.",
  ui_story_5087_50871200_15_dialog_content = "... Dia gila.",
  ui_story_5087_50871200_16_dialog_content = "Nikinis itu gila! Dia sudah menjadi gila!",
  ui_story_5087_50871200_17_dialog_content = "Kamu gila! Kamu marah! Adikku hanya sakit, dan itu melemahkan Luminatics-nya! Dia selalu ada! Aku bisa melihatnya!",
  ui_story_5087_50871200_18_dialog_content = "Yang Mulia, saya mohon. Tolong bantu Nikinis! Sejak Nepolis... Anda tahu, dia sudah seperti ini sejak saat itu...",
  ui_story_5087_50871200_19_dialog_content = "Dokter-dokter bingung! Kamu adalah harapan terakhir kami! Saya mohon, Yang Mulia!",
  ui_story_5087_50871200_20_dialog_content = "...Situasi putri kembar Anda adalah kasus yang sangat langka.",
  ui_story_5087_50871200_21_dialog_content = "Saya memang punya ide, tapi ini terlalu berbahaya. Biarkan saya memikirkannya lebih lanjut.",
  ui_story_5087_50871200_22_dialog_content = "Namamu adalah Nikinis? Itu nama yang indah. Karena kakakmu, Nepolis, tidak suka berbicara, bisakah kamu memperkenalkannya padaku?",
  ui_story_5087_50871200_23_dialog_content = "Apakah kamu baru saja... bertanya tentang adikku? Syukurlah! Akhirnya ada yang percaya padaku!",
  ui_story_5087_50871200_24_dialog_content = "Tapi bisakah kamu merawatnya terlebih dahulu? Dia sakit, dan dia belum sepenuhnya pulih sampai sekarang...",
  ui_story_5087_50871200_25_dialog_content = "Jiwa kita adalah satu, jadi merawatku sendiri tidak akan berhasil... Aku akan baik-baik saja setelah dia baik-baik saja!",
  ui_story_5087_50871200_26_dialog_content = "...",
  ui_story_5087_50871200_27_dialog_content = "Nepolis, Nepolis! Yang Mulia Ratu pasti bisa menyembuhkanmu! Ini adalah berita yang sangat baik!",
  ui_story_5087_50871200_28_dialog_content = "Ya... Aku juga sangat gembira...",
  ui_story_5087_50871200_29_dialog_content = "Jadi, bagaimana kalau bermain petak umpet? Bukan setiap hari kita bisa menghabiskan malam di Istana Musim Dingin. Mari kita bersenang-senang!",
  ui_story_5087_50871200_30_dialog_content = "Tempat ini terasa sangat misterius... Nepolis, apakah kamu juga merasakannya?",
  ui_story_5087_50871200_31_dialog_content = "...",
  ui_story_5087_50871200_32_dialog_content = "Aurorian kecil... Aurorian kecil di sana...",
  ui_story_5087_50871200_33_dialog_content = "Hah? Siapa disana? Siapa yang kamu bicarakan? Apakah itu aku? Atau adikku?",
  ui_story_5087_50871200_34_dialog_content = "Hanya kamu yang bisa melihat saudarimu dan merasakan jiwa-nya. Kesepian, bukan, Aurorian kecil...",
  ui_story_5087_50871200_35_dialog_content = "!",
  ui_story_5087_50871200_36_dialog_content = "Saya... bisa membantu kamu. Kemarilah...",
  ui_story_5087_50871200_37_dialog_content = "... Sebuah cermin? Bagaimana cermin bisa membantuku?",
  ui_story_5087_50871200_38_dialog_content = "Aurorian kecil, kamu tidak tahu apa-apa tentang kekuatan cermin itu.",
  ui_story_5087_50871200_39_dialog_content = "Aku bisa mengembalikan adikmu ke kejayaan semula. Setiap orang akan bisa melihat dan merasakannya—",
  ui_story_5087_50871200_40_dialog_content = "Tetapi kamu harus membuat pakta dengan saya.",
  ui_story_5087_50871200_41_dialog_content = "B-Benarkah itu? Dia akan bermain denganku, bercanda denganku, dan berkelahi denganku, seperti dulu kala?",
  ui_story_5087_50871200_42_dialog_content = "Apa yang harus saya lakukan?",
  ui_story_5087_50871200_43_dialog_content = "Berikan aku... Lumina-mu.",
  ui_story_5087_50871200_44_dialog_content = "Lumina saya? Seperti ini?",
  ui_story_5087_50871200_45_dialog_content = "<color=#e8d9bb>Telapak tangan muda itu menutupi cermin—</color>",
  ui_story_5087_50871200_46_dialog_content = "Relik telah terbangun! Itu menyerap Lumina... Beri tahu Yang Mulia Ratu segera!",
  ui_story_5087_50871200_47_dialog_content = "Anak kecil itu, Nikinis... Dia masih tidak sadar. Northland Mirror telah mengambil terlalu banyak Lumina darinya.",
  ui_story_5087_50871200_48_dialog_content = "Apakah dia akan pernah bangun lagi?",
  ui_story_5087_50871200_49_dialog_content = "Cermin Northland telah memilihnya sebagai tuan rumah. Peluangnya untuk bertahan hidup sangat tipis.",
  ui_story_5087_50871200_50_dialog_content = "... Kecuali jika saya mengunci tubuhnya dengan Northland Mirror.",
  ui_story_5087_50871200_51_dialog_content = "Jika dia bisa beradaptasi dengan peninggalan itu dan kembali sadar sendiri, dia akan bertahan. Jika tidak...",
  ui_story_5087_50871200_52_dialog_content = "Saya kira itu satu-satunya solusi...",
  ui_story_5087_50871200_53_dialog_content = "*menghela nafas* Ini adalah situasi yang persis yang kamu coba hindari dengan tidak merawatnya dengan Cermin Northland.",
  ui_story_5087_50871200_54_dialog_content = "Kita tidak pernah tahu bahwa Northland Mirror akan menariknya... Apakah dia begitu cocok dengan itu?",
  ui_story_5087_50871200_55_dialog_content = "Kamu tidak bisa menyebut itu \"pengobatan.\" Itu hanya memanfaatkan kekuatan Cermin Northland di ranah mental untuk—",
  ui_story_5087_50871200_56_dialog_content = "Paksa hapus sisa-sisa Luminatics yang ditinggalkan oleh saudara perempuannya yang telah meninggal.",
  ui_story_5087_50871200_57_dialog_content = "Luminatics dari satu saudari yang tersisa dalam saudari lainnya memang sangat menakjubkan.",
  ui_story_5087_50871200_58_dialog_content = "Nikinis dan Nepolis adalah spesial. Hubungan mereka sangat dekat sehingga hampir seperti satu jiwa yang terbagi menjadi dua tubuh.",
  ui_story_5087_50871200_59_dialog_content = "Itulah sebabnya perawatan Nikinis harus dilakukan dengan sangat hati-hati. Jika sisa-sisa dari kakaknya dipaksa untuk dihilangkan—",
  ui_story_5087_50871200_60_dialog_content = "Meski dia pasti tidak akan \"melihat\" saudara perempuannya lagi, waktu yang mereka habiskan bersama, kenangan yang mereka bagikan, persepsi yang mereka bentuk bersama...",
  ui_story_5087_50871200_61_dialog_content = "Semua akan menjadi kacau atau bahkan menghilang.",
  ui_story_5087_50871200_62_dialog_content = "Tidak akan berbeda dengan mencabut setengah dari dirinya.",
  ui_story_5087_50871200_63_dialog_content = "Memang. Risiko itu tidak mungkin dihilangkan, bahkan dengan bantuan Northland Mirror sekalipun.",
  ui_story_5087_50871200_64_dialog_content = "Kakak beradik kembar yang terhubung baik dalam pikiran maupun jiwa, tetapi kakaknya jatuh sakit...",
  ui_story_5087_50871200_65_dialog_content = "Dan kematian memisahkan mereka... Mengapa takdir selalu memainkan trik seperti ini pada kita semua?",
  ui_story_5087_50871200_66_dialog_content = "... Tapi apakah mereka benar-benar terpisah?",
  ui_story_5087_50871200_67_dialog_content = "Novio, apakah kamu percaya bahwa... jiwa seorang Aurorian ada di dalam Luminatics?",
  ui_story_5087_50871300_1_dialog_content = "(Aku ingat sekarang, semuanya.)",
  ui_story_5087_50871300_2_dialog_content = "(Nepolis telah lama meninggal, dan Queen Bethlehem menyegel saya di dalam gua beku untuk menyelamatkan hidup saya.)",
  ui_story_5087_50871300_3_dialog_content = "(Kedua orang tua, ibu dan ayah, meninggal selama waktu ini.)",
  ui_story_5087_50871300_4_dialog_content = "(Aku bahkan tidak bisa mengingat hidup bersama orang tuaku setelah sadar kembali...)",
  ui_story_5087_50871300_5_dialog_content = "<color=#e8d9bb>Setelah membuka matanya di dalam gua yang membeku, Aurorian yang dikenal sebagai Nikinis tidak memiliki apa-apa lagi.</color>",
  ui_story_5087_50871300_6_dialog_content = "<color=#e8d9bb>Tanpa rumah, kampung halaman, atau kenangan. Dia sendirian di dunia ini hanya dengan dirinya yang lemah dan tidak sempurna.</color>",
  ui_story_5087_50871300_7_dialog_content = "<color=#e8d9bb>Selain cahaya lembut dari cermin ajaib di sisinya, satu-satunya hal lain yang menyapanya adalah—</color>",
  ui_story_5087_50871300_8_dialog_content = "<color=#e8d9bb>Bayangan dirinya yang tersenyum, berjalan keluar dari antara bunga lili yang sedang mekar penuh yang terpantul di permukaan cermin.</color>",
  ui_story_5087_50871300_9_dialog_content = "\"Apa yang sedang kau tatap? Tidakkah kau mengenali saudarimu sendiri?\"",
  ui_story_5087_50871300_10_dialog_content = "\"Nikinisku... Separuh lain dari diriku...\"",
  ui_story_5087_50871300_11_dialog_content = "(Semua ini... Ini adalah kenyataanku...)",
  ui_story_5087_50871300_12_dialog_content = "(Realitas yang lebih kejam dan mengerikan daripada dunia cermin.)",
  ui_story_5087_50871300_13_dialog_content = "Lalu, mengapa Anda tidak tinggal di dalam cermin?",
  ui_story_5087_50871300_14_dialog_content = "...",
  ui_story_5087_50871300_15_dialog_content = "Kamu lagi... Kamu masih punya keberanian untuk berbicara padaku dengan begitu tak tahu malu...",
  ui_story_5087_50871300_16_dialog_content = "Ini semua salahmu!",
  ui_story_5087_50871300_17_dialog_content = "Jangan terlalu menghakimi... Yang kulakukan hanyalah memenuhi keinginanmu.",
  ui_story_5087_50871300_18_dialog_content = "Kamu ingin menikmati hidup bersama saudarimu, dan aku memberikan itu. Kamu ingin bertarung di sisinya, dan aku juga memberikan itu.",
  ui_story_5087_50871300_19_dialog_content = "Bahkan kenangan tentang kenyataan yang kamu coba pulihkan, aku juga memberikannya kepadamu—meskipun itu tidak akan memberi manfaat apa pun untukku.",
  ui_story_5087_50871300_20_dialog_content = "Oh, aku berharap kamu menunjukkan sedikit rasa terima kasih. Tuan rumah dan kontraktorku...",
  ui_story_5087_50871300_21_dialog_content = "Saya mengambil kembali ingatan saya sendiri! Jangan berpikir untuk mengambil kredit untuk itu!",
  ui_story_5087_50871300_22_dialog_content = "Bagaimana rasanya mengambil kembali kenangan-kenangan itu? Apakah kamu menikmatinya?",
  ui_story_5087_50871300_23_dialog_content = "...",
  ui_story_5087_50871300_24_dialog_content = "Tidak seru, 'kan? Kegelapan dan kebosanan dari kehidupan nyata adalah sesuatu yang saya, pencipta ilusi, tahu lebih baik daripada siapa pun.",
  ui_story_5087_50871300_25_dialog_content = "Jadi, tetap berada di dalam cermin.",
  ui_story_5087_50871300_26_dialog_content = "Aku bisa memenuhi setiap keinginanmu.",
  ui_story_5087_50871300_27_dialog_content = "Apa pun yang bisa dipantulkan oleh cermin adalah hadiah dari saya untuk kamu.",
  ui_story_5087_50871300_28_dialog_content = "Semua yang dibutuhkan hanyalah pikiran untuk kamu menjadi penguasa dunia cermin! Seluruh dunia akan berada di kaki kamu!",
  ui_story_5087_50871300_29_dialog_content = "Atau mungkin keserakahanmu tidak sebesar itu? Mungkin apa yang kamu inginkan hanyalah—",
  ui_story_5087_50871300_30_dialog_content = "Nikinis, aku tidak ingin kehilanganmu lagi...",
  ui_story_5087_50871300_31_dialog_content = "Nepolis!",
  ui_story_5087_50871300_32_dialog_content = "Tetaplah bersamaku. Kamu akan mengabulkan keinginan kecilku ini, bukan?",
  ui_story_5087_50871300_33_dialog_content = "Aku...",
  ui_story_5087_50871300_34_dialog_content = "Jika kamu tetap berada dalam cermin, aku bisa mengambil tempatmu <color=#FFB400>di dunia nyata</color>.",
  ui_story_5087_50871300_35_dialog_content = "Bunga lili akan sekali lagi mekar di Northland... dan bahkan di seluruh tanah Astra.",
  ui_story_5087_50871300_36_dialog_content = "... Sungguh? Itukah keinginanmu?",
  ui_story_5087_50871300_37_dialog_content = "Baik.",
  ui_story_5087_50871300_38_dialog_content = "Baiklah, kalau memang begitu...",
  ui_story_5087_50871300_39_dialog_content = "Akan kulakukan.",
  ui_story_5087_50871400_1_dialog_content = "Aku tidak bisa percaya hutan ini, dataran salju, embun beku, dan segalanya adalah bagian dari ilusi cermin.",
  ui_story_5087_50871400_2_dialog_content = "Tak ada bedanya dengan kenyataan!",
  ui_story_5087_50871400_3_dialog_content = "Nikinis... Nikinis...",
  ui_story_5087_50871400_4_dialog_content = "Dunia cermin itu tidak terlalu buruk, atau lebih tepatnya, tidak ada yang buruk sama sekali tentang itu.",
  ui_story_5087_50871400_5_dialog_content = "Nikinis—",
  ui_story_5087_50871400_6_dialog_content = "Nepolis dan orang tuaku, mereka semua kembali bersamaku lagi...",
  ui_story_5087_50871400_7_dialog_content = "Nikinis!",
  ui_story_5087_50871400_8_dialog_content = "!",
  ui_story_5087_50871400_9_dialog_content = "<color=#e8d9bb>Salju lebat terus turun selama beberapa hari, dan es dan salju di seluruh Northland semakin kristal. Sebuah kristal es bergetar dengan angin dan mendarat di telapak tangan Nikinis.</color>",
  ui_story_5087_50871400_10_dialog_content = "<color=#e8d9bb>Sebuah sosok yang akrab muncul di permukaan kristal es.</color>",
  ui_story_5087_50871400_11_dialog_content = "Yang ada di dalam cermin!",
  ui_story_5087_50871400_12_dialog_content = "Tidak... Saya ingat sekarang. Kamu... PlayerName.",
  ui_story_5087_50871400_13_dialog_content = "Kamu menemukan tempat ini... Apakah kamu melalui semua kesulitan ini hanya untuk membawaku kembali ke kenyataan?",
  ui_story_5087_50871400_14_dialog_content = "Kamu ingat semuanya? Lega sekali! Sekarang dengar, kita harus—",
  ui_story_5087_50871400_15_dialog_content = "... Cukup.",
  ui_story_5087_50871400_16_dialog_content = "Ha?",
  ui_story_5087_50871400_17_dialog_content = "Aku menghargai apa yang telah kau lakukan. Selama aku hidup di dunia nyata, aku tak pernah menyangka ada orang yang akan berusaha sekeras itu untukku.",
  ui_story_5087_50871400_18_dialog_content = "Tapi sekarang sudah baik-baik saja. Istirahatlah. Kamu tidak perlu lagi membuang waktu mencariku.",
  ui_story_5087_50871400_19_dialog_content = "Saya berniat untuk tinggal di dalam cermin.",
  ui_story_5087_50871400_20_dialog_content = "... Apakah ini karena adikmu?",
  ui_story_5087_50871400_21_dialog_content = "\"Saudariku\"... Memang.",
  ui_story_5087_50871400_22_dialog_content = "Meski dia hanyalah ilusi yang diciptakan oleh Northland Mirror dengan mengekstrak sisa-sisa Luminatics-nya dari dalam diriku...",
  ui_story_5087_50871400_23_dialog_content = "Dia masih adik yang sama yang saya kenal.",
  ui_story_5087_50871400_24_dialog_content = "Dia ingin hidup dalam kenyataan lagi, dan bunga lili ingin mekar di seluruh Northland...",
  ui_story_5087_50871400_25_dialog_content = "Bagaimana mungkin aku bisa menolak satu-satunya keinginannya?",
  ui_story_5087_50871400_26_dialog_content = "Apakah itu benar-benar yang diinginkan Nepolis? Kemungkinan besar cermin ajaib itu lagi-lagi memanfaatkan citranya agar kamu tetap tinggal!",
  ui_story_5087_50871400_27_dialog_content = "Sama seperti yang terjadi di Ruang Relik! Itu ingin kamu tetap di cermin sehingga dapat mengendalikan tubuhmu sepenuhnya—",
  ui_story_5087_50871400_28_dialog_content = "Itu masih tidak akan mengubah keputusanku.",
  ui_story_5087_50871400_29_dialog_content = "?",
  ui_story_5087_50871400_30_dialog_content = "Jika kesadaran Nepolis masih ada, dan dia ingin kembali ke realitas dengan bantuan cermin...",
  ui_story_5087_50871400_31_dialog_content = "Maka aku tidak bisa melawan keinginannya dan memadamkan harapannya untuk hidup.",
  ui_story_5087_50871400_32_dialog_content = "Jika Nepolis telah ditelan oleh cermin, dan hanya ilusi darinya yang tersisa...",
  ui_story_5087_50871400_33_dialog_content = "Ini membuktikan bahwa Northland Mirror telah sepenuhnya mengambil alih setengah dari jiwaku.",
  ui_story_5087_50871400_34_dialog_content = "Jika saya kembali ke realitas dalam keadaan seperti itu, bahkan saya tidak dapat memprediksi jenis hal mengerikan apa yang mungkin saya lakukan karena manipulasi.",
  ui_story_5087_50871400_35_dialog_content = "... Kemungkinan aku bahkan akan menyakitimu.",
  ui_story_5087_50871400_36_dialog_content = "Sekarang bukan waktunya untuk mengkhawatirkan aku!",
  ui_story_5087_50871400_37_dialog_content = "Aku tidak punya hak untuk mengabaikan kesejahteraanmu ketika kamu menolak untuk meninggalkanku!",
  ui_story_5087_50871400_38_dialog_content = "Dengarkan aku! Saya tidak pikir Nepolis—",
  ui_story_5087_50871400_39_dialog_content = "PlayerName, beritahu Yang Mulia Ratu untuk menyegelku kembali.",
  ui_story_5087_50871400_40_dialog_content = "Ini satu-satunya cara aku bisa melindungi Nepolis dan kamu—",
  ui_story_5087_50871400_41_dialog_content = "TIDAK! Dengarkan aku saja!",
  ui_story_5087_50871400_42_dialog_content = "Apa…",
  ui_story_5087_50871400_43_dialog_content = "Ada kemungkinan ketiga!",
  ui_story_5087_50871400_44_dialog_content = "Kemungkinan... ketiga?",
  ui_story_5087_50871400_45_dialog_content = "Menurut kamu, Nepolis entah dengan sukarela memilih Northland Mirror, atau cermin itu telah menelannya sejak lama...",
  ui_story_5087_50871400_46_dialog_content = "Tapi itu bukanlah satu-satunya kemungkinan!",
  ui_story_5087_50871400_47_dialog_content = "Bagaimana jika kesadarannya masih ada, dan... dia masih melawan cermin?",
  ui_story_5087_50871400_48_dialog_content = "Dia telah jatuh ke bawah kendali cermin di Ruang Relik...",
  ui_story_5087_50871400_49_dialog_content = "... Tapi bukankah dia mendapatkan kembali kesadarannya pada saat-saat terakhir dan menyelamatkanmu?",
  ui_story_5087_50871400_50_dialog_content = "!",
  ui_story_5087_50871400_51_dialog_content = "N-Nikinis...",
  ui_story_5087_50871400_52_dialog_content = "L-Lari!",
  ui_story_5087_50871400_53_dialog_content = "Melihat kamu lolos dari kendali cermin dan menjalani hidup yang baik adalah apa yang <color=#FFB400>benar-benar diinginkan</color> Nepolis!",
  ui_story_5087_50871400_54_dialog_content = "Nepolis... Keinginan sebenarnya? Dia tidak ingin aku tinggal di dalam cermin? Dia tidak ingin aku tetap di sisinya?",
  ui_story_5087_50871400_55_dialog_content = "... Tentu saja dia ingin bersamamu.",
  ui_story_5087_50871400_56_dialog_content = "Tapi dia lebih suka melihat kamu melebarkan sayapmu, terbang tinggi, dan menjadi jiwa yang bebas dan mandiri!",
  ui_story_5087_50871400_57_dialog_content = "Aku menolak untuk mencabut sayapmu.",
  ui_story_5087_50871400_58_dialog_content = "Lakukan itu, Nikinis.",
  ui_story_5087_50871400_59_dialog_content = "Kamu harus mendapatkan kembali ingatanmu, memahami semuanya, dan kembali untuk menceritakan setiap detail kepadaku.",
  ui_story_5087_50871400_60_dialog_content = "Jadi, lakukan saja. Itu janji.",
  ui_story_5087_50871400_61_dialog_content = "Mengapa... Nepolis? K-Kamu benar-benar masih di sisiku?",
  ui_story_5087_50871400_62_dialog_content = "Meski telah kehilangan bentuk fisiknya, dia masih tetap ada dan berkeinginan untuk melindungimu.",
  ui_story_5087_50871400_63_dialog_content = "Kembali, Nikinis! Cukup kembali ke kenyataan. Kamu bisa meninggalkan cermin dan Nepolis kepada Shaya.",
  ui_story_5087_50871400_64_dialog_content = "Aku yakin dia akan menemukan cara!",
  ui_story_5087_50871400_65_dialog_content = "Shaya... Mawar kuning dan bunga lupa-lupa... Ah! Jangan bilang—",
  ui_story_5087_50871400_66_dialog_content = "Oh, dan ada satu hal lain yang kamu salah paham.",
  ui_story_5087_50871400_67_dialog_content = "Aku belum pernah menjadi satu-satunya yang akan melakukan segalanya dengan segala kemampuanku untukmu.",
  ui_story_5087_50871400_68_dialog_content = "Yang Mulia Ratu, saya selalu ingin memberikan bunga-bunga ini kepada Anda karena mereka melambangkan—",
  ui_story_5087_50871400_69_dialog_content = "Pertemanan yang dihargai, bukan?",
  ui_story_5087_50871400_70_dialog_content = "Kamu telah berkelana di taman selama beberapa hari hingga aku mulai bertanya-tanya kapan kamu akhirnya bersedia memberikan bunga-bunga itu padaku.",
  ui_story_5087_50871400_71_dialog_content = "Shaya adalah Queen Bethlehem yang sebenarnya.",
  ui_story_5087_50871400_72_dialog_content = "Dia memasuki dunia cermin untuk membawamu kembali!",
  ui_story_5087_50871501_1_dialog_content = "Yang Mulia Ratu telah menyatakan Nikinis sebagai kaki tangan dalam pencurian di Winter Palace! Dia saat ini sedang dalam pelarian! Menyembunyikan atau membantunya adalah kejahatan!",
  ui_story_5087_50871501_2_dialog_content = "Para pencuri akan menggunakan cermin untuk membuat kekacauan. Orang-orang Northland!",
  ui_story_5087_50871501_3_dialog_content = "Hancurkan semua cermin segera! Apapun yang bisa mencerminkan gambar seseorang harus dihancurkan!",
  ui_story_5087_50871501_4_dialog_content = "Graah!",
  ui_story_5087_50871501_5_dialog_content = "Graah...",
  ui_story_5087_50871501_6_dialog_content = "Bagaimana situasinya, Nikinis? Urgh, monster-monster ini hanya tidak mau menyerah...",
  ui_story_5087_50871501_7_dialog_content = "Ini tidak terlalu buruk. Apa langkahku selanjutnya?",
  ui_story_5087_50871501_8_dialog_content = "... Beri aku waktu sejenak untuk berpikir. Northland Mirror telah menyadari niatku dan mencoba untuk menghancurkan semua jalan keluar...",
  ui_story_5087_50871501_9_dialog_content = "Perintah untuk menghancurkan semua cermin?",
  ui_story_5087_50871501_10_dialog_content = "Benar. Cermin adalah jalan menuju kenyataan. Stabilitas dan konektivitas sebuah jalan sebanding dengan luas permukaan dan reflektansi cermin.",
  ui_story_5087_50871501_11_dialog_content = "Kristal es kecil ini hanya mampu memfasilitasi komunikasi antara kita pada paling banyak. Itu tidak cukup untuk membawa kamu kembali ke kenyataan.",
  ui_story_5087_50871501_12_dialog_content = "Jadi saya butuh cermin besar dan halus?",
  ui_story_5087_50871501_13_dialog_content = "Tepat sekali. Northland Mirror itu sendiri adalah jalur terbaik. Shaya memasuki dunia ini melaluinya dan mencurinya...",
  ui_story_5087_50871501_14_dialog_content = "Rencananya adalah mengamankan jalur kami sebelum meyakinkan Anda untuk kembali ke kenyataan.",
  ui_story_5087_50871501_15_dialog_content = "Sayangnya, ratu palsu itu selangkah lebih maju dari kami dan memerintahkan monster yang tinggal di dalam Cermin Northland untuk menghancurkannya...",
  ui_story_5087_50871501_16_dialog_content = "... Dia menghancurkan cermin? Dan dia bahkan berpura-pura membuat kakakku dan saya mencarinya!",
  ui_story_5087_50871501_17_dialog_content = "PlayerName, kamu mengenal Winter Palace seperti telapak tanganmu—",
  ui_story_5087_50871501_18_dialog_content = "Apakah ada cara untuk menyelinap kembali ke Room of Relics dan menuju ke Northland Mirror?",
  ui_story_5087_50871501_19_dialog_content = "Saya khawatir Ruang Relik mungkin adalah lokasi yang paling dijaga ketat di Northland...",
  ui_story_5087_50871501_20_dialog_content = "Maka kita harus melupakan Northland Mirror dan fokus mencari cara lain.",
  ui_story_5087_50871501_21_dialog_content = "Sekarang setelah ratu palsu telah memerintahkan penghancuran semua cermin, mengamankan jalan lain sama sekali tidak akan mudah... Tapi kamu benar! Tak ada jalan lain!",
  ui_story_5087_50871501_22_dialog_content = "Kamu tampak tenang secara tak terduga, Nikinis. Rasanya seperti saya sedang melihat sosokmu yang mengagumkan dan tak terkalahkan di medan perang lagi.",
  ui_story_5087_50871501_23_dialog_content = "... Karena Nepolis sudah pergi.",
  ui_story_5087_50871501_24_dialog_content = "Dulu, aku tidak memiliki siapa pun untuk mengandalkan atau memanjakanku.",
  ui_story_5087_50871501_25_dialog_content = "Nikinis...",
  ui_story_5087_50871501_26_dialog_content = "Kamu memilih untuk menempuh jalan tanpa adikmu.",
  ui_story_5087_50871501_27_dialog_content = "!",
  ui_story_5087_50871501_28_dialog_content = "<color=#e8d9bb>Salju berhamburan dengan angin, seperti prajurit menakutkan yang bersiul melalui angin saat mereka menjawab panggilan drum perang—</color>",
  ui_story_5087_50871501_29_dialog_content = "<color=#e8d9bb>Mengawal sosok yang mendekat dengan kakinya dan membungkuk di depan tatapan dinginnya.</color>",
  ui_story_5087_50871501_30_dialog_content = "Ini \"queen\"! Di antara semua pantulan Cermin Northland...",
  ui_story_5087_50871501_31_dialog_content = "... Dia yang terkuat.",
  ui_story_5087_50871501_32_dialog_content = "Karena kamu sadar akan hal itu, menyerahlah saja, Nikinis.",
  ui_story_5087_50871501_33_dialog_content = "Kehidupan yang tenang dan nyaman bersama orang tua dan kakakmu. Cukup katakan dan itu akan menjadi milikmu.",
  ui_story_5087_50871501_34_dialog_content = "... Tapi aku harus berbaring di salju gelap dan melupakan sayapku.",
  ui_story_5087_50871501_35_dialog_content = "Apakah kamu benar-benar ingin sayap-sayap yang sebagian hancur itu?",
  ui_story_5087_50871501_36_dialog_content = "Mereka hanya akan membawa rasa sakit padamu. Setiap kali sayap itu bergerak tanpa hasil adalah sebuah pengingat—",
  ui_story_5087_50871501_37_dialog_content = "Ini mengingatkanku bahwa Nepolis pernah ada di sini.",
  ui_story_5087_50871501_38_dialog_content = "!",
  ui_story_5087_50871501_39_dialog_content = "Ini mengingatkan saya pada kegembiraan dan kebebasan yang kita bagikan saat membubung bersama.",
  ui_story_5087_50871501_40_dialog_content = "Nepolis akan kecewa jika aku meninggalkan kenangan-kenangan itu.",
  ui_story_5087_50871501_41_dialog_content = "Aku tidak akan pernah mengecewakan adik perempuanku.",
  ui_story_5087_50871501_42_dialog_content = "... Jika itu keputusanmu—",
  ui_story_5087_50871501_43_dialog_content = "Nikinis! Hati-Hati!",
  ui_story_5087_50871501_44_dialog_content = "Argh!",
  ui_story_5087_50871501_45_dialog_content = "<color=#e8d9bb>Salju menyapu bayangan yang seakan-akan hampir membekukan dunia di sekitarnya.</color>",
  ui_story_5087_50871501_46_dialog_content = "<color=#e8d9bb>Kekuatan \"queen\" jauh melampaui kebanyakan Aurorian.</color>",
  ui_story_5087_50871501_47_dialog_content = "<color=#e8d9bb>Nikinis memberikan segalanya yang dia miliki, namun dia hampir tidak mampu membela dirinya sendiri dan kristal es kecil di genggamannya.</color>",
  ui_story_5087_50871501_48_dialog_content = "Apakah kristal es yang rapuh itu cermin terakhirmu? Sungguh kasihan.",
  ui_story_5087_50871501_49_dialog_content = "Setiap kristal salju di Northland... adalah subjek milikku!",
  ui_story_5087_50871501_50_dialog_content = "... Aku... tidak akan... membiarkanmu... mengambil cerminku! Aaaah!",
  ui_story_5087_50871501_51_dialog_content = "Cermin... Tunggu sebentar! Kita masih punya satu cermin lagi! Bagaimana bisa aku lupa?",
  ui_story_5087_50871501_52_dialog_content = "Yah, belum terlambat.",
  ui_story_5087_50871501_53_dialog_content = "!",
  ui_story_5087_50871501_54_dialog_content = "Shaya? Tidak, kamu...",
  ui_story_5087_50871501_55_dialog_content = "Kalian berdua telah melakukan dengan baik, PlayerName dan Nikinis.",
  ui_story_5087_50871501_56_dialog_content = "Dan kamu... Aku percaya saat pembalasan telah tiba.",
  ui_story_5087_50871501_57_dialog_content = "...",
  ui_story_5087_50871501_58_dialog_content = "Menari untukku! Salju Northland!",
  ui_story_5087_50871502_1_dialog_content = "<color=#e8d9bb>Salju perak meluncur di udara dengan megah dan menghentikan salju gelap yang mengamuk dari mendekat.</color>",
  ui_story_5087_50871502_2_dialog_content = "Minggir.",
  ui_story_5087_50871502_3_dialog_content = "Berhenti berusaha menjadi pahlawan ketika kamu hanya anjing liar yang harus menyelinap ke Istana Musim Dingin!",
  ui_story_5087_50871502_4_dialog_content = "Anda bukan ratu di sini!",
  ui_story_5087_50871502_5_dialog_content = "... Kamu tidak tahu apa-apa tentang memerintah.",
  ui_story_5087_50871502_6_dialog_content = "Salju Northland tidak memerlukan penguasa. Begitu pula dengan penduduk Northland yang hidup berdampingan dengan salju, mereka tidak memerlukan belenggu yang tidak perlu.",
  ui_story_5087_50871502_7_dialog_content = "Alasan tunggal eksistensi penguasa adalah untuk mewarisi kekuatan melindungi Northland.",
  ui_story_5087_50871502_8_dialog_content = "Mungkin aku adalah ratu, tapi aku terlebih dahulu dan terutama adalah seorang pejuang Northland—",
  ui_story_5087_50871502_9_dialog_content = "Kamu pikir aku akan membiarkanmu menyentuh teman-temanku begitu saja? Kenapa tidak coba lewati badai saljuku terlebih dahulu?",
  ui_story_5087_50871502_10_dialog_content = "Yang Mulia...",
  ui_story_5087_50871502_11_dialog_content = "Betapa konyolnya!",
  ui_story_5087_50871502_12_dialog_content = "Tidak ada yang cocok untuk saya di dunia cermin!",
  ui_story_5087_50871502_13_dialog_content = "Yang Mulia, biarkan aku membantu Anda! Urgh! Oh tidak—",
  ui_story_5087_50871502_14_dialog_content = "<color=#e8d9bb>Angin gale perak dan salju gelap bertabrakan seperti behemoth yang bisa membalikkan dunia.</color>",
  ui_story_5087_50871502_15_dialog_content = "<color=#e8d9bb>Dalam sekejap ketidakhati-hatian, kristal es kecil itu terlepas dari genggaman Nikinis dan diterbangkan oleh badai.</color>",
  ui_story_5087_50871502_16_dialog_content = "PlayerName!",
  ui_story_5087_50871502_17_dialog_content = "Jangan khawatir tentang saya! Buruan ke <color=#FFB400>Lake Mirror</color>!",
  ui_story_5087_50871502_18_dialog_content = "Danau Cermin... Itu rumahmu! Dan itu adalah... jalan terakhirmu...",
  ui_story_5087_50871502_19_dialog_content = "Ini adalah cermin terbesar, terterang, dan paling stabil di Northland—serta yang paling akrab dengan kamu!",
  ui_story_5087_50871502_20_dialog_content = "<color=#e8d9bb>Kristal es itu ditelan oleh badai, dan suara Caelestite tidak terdengar lagi.</color>",
  ui_story_5087_50871502_21_dialog_content = "<color=#e8d9bb>Hanya desisan angin salju yang tersisa di sekitar Nikinis.</color>",
  ui_story_5087_50871502_22_dialog_content = "<color=#e8d9bb>Orang-orang yang akan melakukan segala yang mereka bisa untuknya masih berjuang untuknya pada saat ini, dan itu adalah buktinya.</color>",
  ui_story_5087_50871502_23_dialog_content = "Terima kasih, Shaya... Queen Bethlehem...",
  ui_story_5087_50871502_24_dialog_content = "Aku tidak akan mengecewakanmu!",
  ui_story_5087_50871601_1_dialog_content = "<color=#e8d9bb>Dunia mungkin berubah, dan badai mungkin mengamuk, tetapi Lake Mirror tetap tidak berubah.</color>",
  ui_story_5087_50871601_2_dialog_content = "<color=#e8d9bb>Itu beristirahat di sana dengan tenang di antara pegunungan, jernih seperti cermin, dan tetap seperti biasanya.</color>",
  ui_story_5087_50871601_3_dialog_content = "<color=#e8d9bb>Ini memberikan hembusan angin sejuk, udara yang damai, dan aroma bunga yang lembut pada sosok Nikinis yang gagah.</color>",
  ui_story_5087_50871601_4_dialog_content = "<color=#e8d9bb>Aroma lembut namun kaya dari bunga putih murni.</color>",
  ui_story_5087_50871601_5_dialog_content = "(Lapangan bunga di Lake Mirror... Hanya beberapa hari yang lalu, saya menikmati pemandangan di sini bersama Nepolis...)",
  ui_story_5087_50871601_6_dialog_content = "<color=#e8d9bb>Nikinis dengan lembut mengelus bunga-bunga putih. Narcissus dan lili tumbuh dalam harmoni di tepi danau yang tenang.</color>",
  ui_story_5087_50871601_7_dialog_content = "<color=#e8d9bb>Sebuah pemandangan indah yang selalu membuat jantungnya berdebar. Dia tidak pernah berhenti mencoba untuk menemukan makna dari itu semua.</color>",
  ui_story_5087_50871601_8_dialog_content = "Mari coba lagi, PlayerName. Saya lebih memilih untuk tidak dihukum hidup mengembara, arogan, membosankan, dan tanpa kenangan...",
  ui_story_5087_50871601_9_dialog_content = "Dan bahkan tidak mengetahui alasan dari kesedihanku.",
  ui_story_5087_50871601_10_dialog_content = "Aku mulai mengingat hal-hal... Tolong bantu aku dengan kemampuan psikis Anda lagi!",
  ui_story_5087_50871601_11_dialog_content = "Baiklah... Tapi jangan memaksakan diri. Kita berhenti jika kamu merasa tidak nyaman, oke?",
  ui_story_5087_50871601_12_dialog_content = "\"Apa kamu ingat...\"",
  ui_story_5087_50871601_13_dialog_content = "!",
  ui_story_5087_50871601_14_dialog_content = "<color=#e8d9bb>Api ceria membakar di perapian, cahaya hangatnya menciptakan bayangan yang menari dalam pondok kecil.</color>",
  ui_story_5087_50871601_15_dialog_content = "<color=#e8d9bb>Di bawah cahaya api, empat sosok dapat terlihat: suami dan istri, serta putri kembar mereka yang tampak seperti cerminan satu sama lain.</color>",
  ui_story_5087_50871601_16_dialog_content = "\"Dapatkah kamu mengingat bunga putih yang indah itu? Sepasang tumbuh dalam harmoni di tepi danau yang tenang.\"",
  ui_story_5087_50871601_17_dialog_content = "...",
  ui_story_5087_50871601_18_dialog_content = "\"PlayerName, Saya ingat sekarang.\"",
  ui_story_5087_50871601_19_dialog_content = "\"Hanya kenangan singkat orang tua kita menceritakan cerita kepada kita.\"",
  ui_story_5087_50871601_20_dialog_content = "\"Tapi aku yakin, ingatan ini yang menyembunyikan kebenaran di balik ingatan yang hilangku...\"",
  ui_story_5087_50871601_21_dialog_content = "\"Mengapa aku tidak ingat tinggal bersama orang tuaku?\"",
  ui_story_5087_50871601_22_dialog_content = "\"Mengapa Nepolis terkurung hidup di dalam cermin?\"",
  ui_story_5087_50871601_23_dialog_content = "\"Kenapa aku selalu tidak bahagia seolah-olah ada jurang tak berdasar di hatiku?\"",
  ui_story_5087_50871601_24_dialog_content = "\"Jawaban yang saya cari pasti tersembunyi dalam cermin ajaib yang tidak pernah meninggalkan sisiku...\"",
  ui_story_5087_50871601_25_dialog_content = "\"Jadi, aku akan masuk ke dalam cermin. Nepolis ada di sana, dan akhirnya aku akan pergi ke sisinya.\"",
  ui_story_5087_50871601_26_dialog_content = "\"Terima kasih, PlayerName.\"",
  ui_story_5087_50871601_27_dialog_content = "Pesan selesai.",
  ui_story_5087_50871601_28_dialog_content = "<color=#e8d9bb>Cermin di depan menunggu dengan cahaya lembut dan halus, seperti hari Nikinis terbangun di gua beku.</color>",
  ui_story_5087_50871601_29_dialog_content = "<color=#e8d9bb>Nikinis mengambil napas dalam-dalam dan melangkah maju menuju bayangan dirinya di cermin...</color>",
  ui_story_5087_50871601_30_dialog_content = "(Itulah bagaimana saya masuk ke dunia cermin dan terbangun di ladang bunga ini...)",
  ui_story_5087_50871601_31_dialog_content = "(Saya berjalan-jalan bergandengan tangan dengan saudara perempuan saya dan menikmati kegembiraan bebas yang ditawarkan tempat ini.)",
  ui_story_5087_50871601_32_dialog_content = "(Jika saja saya bisa tenggelam dalam mimpi ini... Tapi—)",
  ui_story_5087_50871601_33_dialog_content = "Nikinis, aku telah membawa umbi bunga lili baru untukmu. Kita bisa menanamnya di ruang kosong di sana!",
  ui_story_5087_50871601_34_dialog_content = "Wow! Keindahan ladang bunga Nikinis ini tidak pernah berhenti tumbuh! Aku akan membawa beberapa benih lain kali.",
  ui_story_5087_50871601_35_dialog_content = "(Lapangan bunga begitu subur dan indah berkat bantuan banyak orang Northland.)",
  ui_story_5087_50871601_36_dialog_content = "Nikinis, aku akan membantu membajak tanah! Ho! Ini benar-benar membeku keras.",
  ui_story_5087_50871601_37_dialog_content = "Aku akan membantu menyiram!",
  ui_story_5087_50871601_38_dialog_content = "(Ini adalah air dari salju Northland yang mencair yang memungkinkan bunga narcissus yang lembut untuk tumbuh dan mekar.)",
  ui_story_5087_50871601_39_dialog_content = "Mimpi ini... Saatnya bangun.",
  ui_story_5087_50871601_40_dialog_content = "Mengapa? Apakah kamu sudah lupa akhir cerita ini?",
  ui_story_5087_50871601_41_dialog_content = "Akhir cerita...",
  ui_story_5087_50871601_42_dialog_content = "\"Dari hari itu, bunga lili mekar dari narkissos, dan mereka berdua hidup bahagia selama-lamanya.\"",
  ui_story_5087_50871601_43_dialog_content = "Bagaimana bisa kamu berpikir untuk meninggalkanku lagi setelah berjanji akan memberiku akhir seperti itu?",
  ui_story_5087_50871601_44_dialog_content = "Nikinis!",
  ui_story_5087_50871601_45_dialog_content = "Tidak, bukan itu! Saya—",
  ui_story_5087_50871601_46_dialog_content = "<color=#e8d9bb>Nikinis hendak membela diri ketika dia terdiam melihat \"sister\"nya.</color>",
  ui_story_5087_50871601_47_dialog_content = "Kamu bukan kakakku... Kamu adalah cermin...",
  ui_story_5087_50871601_48_dialog_content = "Nepolis akhirnya kalah juga olehmu...",
  ui_story_5087_50871601_49_dialog_content = "Kalah? Menang? Semua itu hanya imajinasimu, Nikinis.",
  ui_story_5087_50871601_50_dialog_content = "Aku adalah kakakmu, dan dia adalah aku. Satu-satunya pilihan yang kamu miliki adalah percaya!",
  ui_story_5087_50871601_51_dialog_content = "Kalau tidak, bukankah itu akan membuatmu tidak punya pilihan selain melawanku?",
  ui_story_5087_50871601_52_dialog_content = "Aku—",
  ui_story_5087_50871601_53_dialog_content = "Menghentikanku, meremukkanku, menginjak-injak keinginanku, dan menghancurkan harapanku untuk bertahan hidup... Apakah kamu benar-benar mampu melakukan semua itu?",
  ui_story_5087_50871601_54_dialog_content = "Kamu tidak bisa, bukan? Karena kamu adalah Nikinis, bunga narkissos yang mencintai bunga lili...",
  ui_story_5087_50871601_55_dialog_content = "Tidak, aku... Kamu bukan...",
  ui_story_5087_50871601_56_dialog_content = "Sekarang, kembali ke sisiku. Izinkan saya menggantikanmu dan mencari kebebasan... Urgh—",
  ui_story_5087_50871601_57_dialog_content = "Argh... Aaaaahhh!",
  ui_story_5087_50871601_58_dialog_content = "... Nikinis...",
  ui_story_5087_50871601_59_dialog_content = "Nepolis?",
  ui_story_5087_50871601_60_dialog_content = "Nepolis, apakah itu kamu? Kamu masih di sini? Kamu benar-benar... Ini bukan imajinasiku. Kamu tidak kalah padanya—",
  ui_story_5087_50871601_61_dialog_content = "... Akhir... cerita...",
  ui_story_5087_50871601_62_dialog_content = "Akhirnya? Oh, begitu. Jadi kamu memang ingin hidup lagi, bukan?",
  ui_story_5087_50871601_63_dialog_content = "Tentu saja, hanya benar jika kamu hidup dan mengambil tempatku di dunia nyata—",
  ui_story_5087_50871601_64_dialog_content = "Bukan...",
  ui_story_5087_50871601_65_dialog_content = "?",
  ui_story_5087_50871601_66_dialog_content = "\"Meski bunga lili kembali, kesuciannya telah hilang. Dia menjadi bunga hitam yang ternoda oleh salju yang tercemar.\"",
  ui_story_5087_50871601_67_dialog_content = "Itu adalah... akhir yang sebenarnya...",
  ui_story_5087_50871601_68_dialog_content = "Nepolis, apa yang kamu katakan—",
  ui_story_5087_50871601_69_dialog_content = "Cermin ajaib dan aku sekarang tidak bisa dipisahkan, dan aku bukan lagi siapa aku dulu. Saatnya... untuk aku pergi.",
  ui_story_5087_50871601_70_dialog_content = "Tapi, itu berbeda untukmu.",
  ui_story_5087_50871601_71_dialog_content = "Aku tidak ingin mendengar sepatah kata pun lagi! Nepolis... Semuanya akan baik-baik saja...",
  ui_story_5087_50871601_72_dialog_content = "Nikinis, kakakku yang sangat kucintai, tidak akan berbaring di salju yang gelap.",
  ui_story_5087_50871601_73_dialog_content = "Dia akan menyeberangi salju dan mengatasi penderitaan yang dibawa oleh takdir...",
  ui_story_5087_50871601_74_dialog_content = "Dia akan melampaui perlindungan adiknya untuk melihat dunia dan mencintai lebih banyak orang...",
  ui_story_5087_50871601_75_dialog_content = "Dia akan tumbuh dengan martabat dan kekuatan untuk melindungi warisan, dongeng, dan puisi Northland, dan dia akan menyebarkan berkah bunga ke tanah yang jauh...",
  ui_story_5087_50871601_76_dialog_content = "Dia akan mengambil apa yang terlupakan, mengambil kembali apa yang hilang, dan menulis akhir dari puisi kita sehingga ode baru dapat lahir!",
  ui_story_5087_50871601_77_dialog_content = "Jadi, bertarung.",
  ui_story_5087_50871601_78_dialog_content = "!",
  ui_story_5087_50871601_79_dialog_content = "Hancurkan aku, musnahkan aku, dan akhiri aku, sehingga Cermin Ajaib tidak akan memiliki apa-apa lagi untuk diandalkan!",
  ui_story_5087_50871601_80_dialog_content = "Izinkan aku mengembalikan masa depan yang pantas untukmu, sehingga kamu dapat terbang tinggi dengan sayapmu—",
  ui_story_5087_50871601_81_dialog_content = "Aku percaya padamu.",
  ui_story_5087_50871601_82_dialog_content = "Nepolis...",
  ui_story_5087_50871601_83_dialog_content = "Argh... Argh... Aaaah!",
  ui_story_5087_50871601_84_dialog_content = "Hehe... Pada akhirnya, kamu masih keras kepala menolak untuk menerima satu-satunya jalan menuju kebahagiaan, ya? Kakakku...",
  ui_story_5087_50871601_85_dialog_content = "NEPOLIS! Aahhhh!",
  ui_story_5087_50871602_1_dialog_content = "<color=#e8d9bb>Pantulan hijau gelap dari Aurora berkelok-kelok di perairan Lake Mirror seperti ular yang meluncur di bawah permukaannya.</color>",
  ui_story_5087_50871602_2_dialog_content = "<color=#e8d9bb>Teriakan dan benturan pertempuran telah mereda. Jernih seperti cermin, dan sama seperti biasanya, abadi adalah Lake Mirror.</color>",
  ui_story_5087_50871602_3_dialog_content = "...",
  ui_story_5087_50871602_4_dialog_content = "<color=#e8d9bb>\"Aku akan ada di sana saat kamu membutuhkanku...\"</color>",
  ui_story_5087_50871602_5_dialog_content = "<color=#e8d9bb>Kata-kata terakhir Nepolis masih terngiang di telinga Nikinis.</color>",
  ui_story_5087_50871602_6_dialog_content = "<color=#e8d9bb>Dia berdiri di sana dengan diam di antara kelopak-kelopak putih murni yang terkoyak dan berterbangan.</color>",
  ui_story_5087_50871602_7_dialog_content = "<color=#e8d9bb>Aroma bunga yang memabukkan mengisi udara.</color>",
  ui_story_5087_50871602_8_dialog_content = "Nikinis! Kamu berhasil!",
  ui_story_5087_50871602_9_dialog_content = "Jika kamu tidak menghentikan cermin ajaib tepat waktu, PlayerName dan aku mungkin tidak akan selamat! Kamu telah menyelamatkan kami!",
  ui_story_5087_50871602_10_dialog_content = "... Itu menyeramkan! Aku rasa aku tidak akan bisa tahan melihat salju lagi...",
  ui_story_5087_50871602_11_dialog_content = "Jangan bilang begitu! Kamu akan merasa bosan dengan pemandangan salju di Northland.",
  ui_story_5087_50871602_12_dialog_content = "Nikinis, maafkan aku telah membuatmu menghadapi segalanya sendirian...",
  ui_story_5087_50871602_13_dialog_content = "Aku baik-baik saja, Your Majesty. Dan... PlayerName—",
  ui_story_5087_50871602_14_dialog_content = "Terima kasih.",
  ui_story_5087_50871602_15_dialog_content = "... Kelihatannya kamu tidak perlu diyakinkan lagi.",
  ui_story_5087_50871602_16_dialog_content = "Saya akan melihat kamu di sisi lain!",
  ui_story_5087_50871602_17_dialog_content = "Hei! T-Tunggu sebentar! Shaya! Apa yang kamu lakukan... Ahhhhh! Kita akan terjun? Aku butuh lebih banyak waktu untuk mempersiapkan diri untuk ini—",
  ui_story_5087_50871602_18_dialog_content = "<color=#e8d9bb>Ciprat! Gelombang melanda danau, namun segera kembali tenang lagi.</color>",
  ui_story_5087_50871602_19_dialog_content = "<color=#e8d9bb>Aroma bunga melayang lewat Nikinis. Dia sekali lagi ditinggalkan sendirian di antara bunga-bunga di ladang itu.</color>",
  ui_story_5087_50871602_20_dialog_content = "Nepolis...",
  ui_story_5087_50871602_21_dialog_content = "Waktunya pergi ke dunia yang telah kau perjuangkan keras untukku... dunia tanpa dirimu.",
  ui_story_5087_50871602_22_dialog_content = "Aku harus hidup dengan baik meskipun kamu tidak ada di sana... Benar?",
  ui_story_5087_50871602_23_dialog_content = "<color=#e8d9bb>Nikinis perlahan mendekati Lake Mirror. Andai saja dia bisa tinggal di tepi danau sedikit lebih lama, hanya sedikit lebih lama.</color>",
  ui_story_5087_50871602_24_dialog_content = "<color=#e8d9bb>Sayangnya, dia hanya butuh beberapa langkah untuk mencapai tepi danau. Nikinis menunduk saat air danau membasahi ujung gaunnya—</color>",
  ui_story_5087_50871602_25_dialog_content = "N-Nepolis?",
  ui_story_5087_50871602_26_dialog_content = "<color=#e8d9bb>Figur Nikinis dan Nepolis terpantul di permukaan danau.</color>",
  ui_story_5087_50871602_27_dialog_content = "<color=#e8d9bb>Kembaran itu menari di tepi danau, ditemani oleh bintik-bintik putih murni yang berterbangan dengan angin—sebuah tarian salju yang melayang dan kelopak yang jatuh.</color>",
  ui_story_5087_50871602_28_dialog_content = "<color=#e8d9bb>Menari! Menari selamanya hingga akhir waktu!</color>",
  ui_story_5087_50871602_29_dialog_content = "<color=#e8d9bb>Ini akan menjadi akhir cerita yang benar-benar indah—sebuah puisi cantik yang hanya diketahui oleh angin dan salju.</color>",
  ui_story_5087_50871602_30_dialog_content = "Saudariku... Aku akan ada saat kau membutuhkanku...",
  ui_story_5087_50871602_31_dialog_content = "<color=#e8d9bb>Ciprat! Gelombang kecil melanda danau sekali lagi.</color>",
  ui_story_5087_50871602_32_dialog_content = "<color=#e8d9bb>Namun, refleksi indah dan puitis itu tetap ada.</color>",
  ui_story_5087_50871602_33_dialog_content = "<color=#e8d9bb>Tetap dikelilingi oleh salju, berkilauan di dalam cermin...</color>"
}
return config
